-- ----------------------------
-- Table structure for article
-- ----------------------------
DROP TABLE IF EXISTS `article`;
CREATE TABLE `article`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '文章ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标题',
  `cover` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '文章封面',
  `author_id` bigint UNSIGNED NOT NULL COMMENT '作者ID',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态（0-草稿，1-发布,2-下架,3-删除）',
  `view_count` bigint NULL DEFAULT 0 COMMENT '阅读量',
  `summary` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文章摘要',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_top` tinyint NOT NULL DEFAULT 0 COMMENT '0:不置顶，1：置顶',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_author_id`(`author_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文章表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of article
-- ----------------------------
INSERT INTO `article` VALUES (6, 'EasyExcel写入和读取多个sheet', 'https://xzf-blog.oss-cn-shanghai.aliyuncs.com/687849dcd86a4052994cf3e5ea497867.png', 2, 1, 149, '文章介绍如何使用EasyExcel库读写包含多个sheet的Excel文件，包括依赖、实体类定义和核心代码示例。', '2026-01-24 04:00:22', '2026-02-09 18:01:15', 1);
INSERT INTO `article` VALUES (21, '详解Mysql的MVCC实现原理', 'https://xzf-blog.oss-cn-shanghai.aliyuncs.com/0a2bc1448f5c45ea93152c0610f293c3.png', 2, 1, 29, 'MVCC是InnoDB实现读已提交和可重复读隔离级别的机制，通过隐藏字段、undo log和Read View快照实现。它利用版本链和可见性判断规则，在快照读时无需加锁即可解决读写冲突，提升并发性能。', '2026-01-31 23:06:05', '2026-02-09 17:57:46', 0);
INSERT INTO `article` VALUES (22, 'Zookeeper入门部署（单点与集群）', 'https://xzf-blog.oss-cn-shanghai.aliyuncs.com/bc40a640d44948329f01126a36e8b9a8.png', 2, 1, 5, '本文介绍了Zookeeper单点与集群的部署操作，包括启动、关闭和重启服务的命令示例，并建议读者可自行修改脚本以扩展功能。', '2026-02-03 01:53:26', '2026-02-09 17:57:42', 0);
INSERT INTO `article` VALUES (23, '深入多线程锁：synchronized篇', 'https://xzf-blog.oss-cn-shanghai.aliyuncs.com/eda2943d1ef844fe8f26bd51edea8ec5.png', 2, 1, 6, '本文深入探讨了Java多线程中的synchronized锁机制。文章首先介绍了synchronized如何基于JMM保证原子性、有序性和可见性。接着详细说明了其两种基本使用方式：同步方法和同步代码块，并指出静态与非静态方法锁对象的区别。核心部分阐述了JDK 1.6后的锁升级优化过程，包括无锁、偏向锁、轻量级锁和重量级锁四种状态及其转换条件。最后，文章结合对象头中的MarkWord和Lock Record，解析了synchronized在不同锁状态下的底层实现原理与获取锁的具体流程。', '2026-02-03 01:55:05', '2026-02-09 17:57:43', 0);
INSERT INTO `article` VALUES (24, '解决MethodArgumentTypeMismatchException', 'https://xzf-blog.oss-cn-shanghai.aliyuncs.com/0506e3027b2543a1b692286530d4a285.png', 2, 1, 8, '文章介绍了在SpringBoot项目中，使用枚举类型作为接口参数时，遇到MethodArgumentTypeMismatchException异常的解决方法。问题源于Spring MVC、MyBatis和JSON序列化时，默认转换器无法将数字字符串映射到自定义枚举。解决方案包括：为Spring MVC添加自定义Converter或ConverterFactory；为MyBatis-Plus的枚举字段添加@EnumValue注解；为JSON序列化添加@JsonValue注解。', '2026-02-03 01:57:01', '2026-02-09 17:56:35', 0);
INSERT INTO `article` VALUES (25, '解析LoadBalancer负载均衡底层原理', 'https://xzf-blog.oss-cn-shanghai.aliyuncs.com/4f4ffab246504a4faf0f0b59809cc39d.png', 2, 1, 8, '本文解析了Spring Cloud LoadBalancer的底层原理。LoadBalancer是客户端负载均衡器，从注册中心获取服务列表并缓存，通过算法选择实例。文章详细介绍了其默认的轮询算法（RoundRobinLoadBalancer）和Nacos默认的加权随机算法（NacosLoadBalancer）的核心源码与实现逻辑，并说明了如何修改为随机算法或自定义算法。', '2026-02-03 01:58:15', '2026-02-09 17:56:35', 0);
INSERT INTO `article` VALUES (26, '自定义注解（结合SpringAOP）', 'https://xzf-blog.oss-cn-shanghai.aliyuncs.com/c70217a42962477f839859148e8b3555.png', 2, 1, 6, '本文介绍了Java元注解（@Target、@Retention、@Documented、@Inherited、@Repeatable）的作用，并通过一个结合Spring AOP的自定义注解案例，详细展示了如何创建注解、定义AOP切面来计算方法耗时，并进行了测试验证。', '2026-02-03 01:58:47', '2026-02-09 17:56:32', 0);
INSERT INTO `article` VALUES (27, 'ThreadLocal原理详解', 'https://xzf-blog.oss-cn-shanghai.aliyuncs.com/17c6edb4572540b3aa9787ec61291c2c.png', 2, 1, 10, '本文详细解析了ThreadLocal的原理。ThreadLocal通过ThreadLocalMap实现线程隔离，每个线程拥有独立的ThreadLocalMap实例，以ThreadLocal对象为键存储变量。其get()和set()方法通过当前线程访问对应的ThreadLocalMap进行操作。需注意Entry的key为弱引用，但value为强引用，使用后应调用remove()避免内存泄漏。', '2026-02-03 01:59:15', '2026-02-09 17:56:31', 0);
INSERT INTO `article` VALUES (28, 'Zookeeper分布式锁实现', 'https://xzf-blog.oss-cn-shanghai.aliyuncs.com/ae81641503f74f098717c03f95d4a5e3.png', 2, 1, 9, '本文介绍了Zookeeper分布式锁的实现原理与两种实现方式。Zookeeper通过目录树管理节点，利用临时有序节点和监听机制实现分布式锁：客户端在指定目录下创建临时有序节点，若节点序号最小则获得锁，否则监听前序节点，待其删除后获得锁。文章详细展示了手写简易分布式锁的Java代码，并介绍了使用Curator框架简化开发，后者支持可重入锁等高级特性。', '2026-02-03 02:00:34', '2026-02-09 17:56:17', 0);
INSERT INTO `article` VALUES (29, '（转载）Java线程池实现原理', 'https://xzf-blog.oss-cn-shanghai.aliyuncs.com/23e7988b46594e8f875e15b78d0ecc45.png', 2, 1, 10, '本文介绍了Java线程池（ThreadPoolExecutor）的实现原理。线程池通过池化思想管理线程，降低资源消耗、提高响应速度与可管理性。其核心设计包括任务管理（调度、缓冲、拒绝）和线程管理（Worker线程的生命周期控制）。线程池内部使用生产者-消费者模型，通过阻塞队列解耦任务与线程，根据线程数量与队列状态动态调整任务执行策略。', '2026-02-03 02:10:22', '2026-02-09 17:56:13', 0);
INSERT INTO `article` VALUES (30, '（转载）Java线程池在美团业务中的实践', 'https://xzf-blog.oss-cn-shanghai.aliyuncs.com/23e7988b46594e8f875e15b78d0ecc45.png', 2, 1, 10, '本文介绍了美团业务中线程池的实践，包括快速响应用户请求和批量任务处理两种典型场景，并分析了线程池参数配置不当引发的故障。为解决参数配置难题，文章提出了动态化线程池方案，通过简化配置、支持参数动态修改和增加监控告警功能，降低故障风险，提升线程池使用的安全性和易用性。', '2026-02-03 02:13:50', '2026-02-09 17:56:11', 0);

