INSERT INTO `article_content` VALUES (5, 6, '<p>最近在工作中，作者频频接触到Excel处理，因此也对EasyExcel进行了一定的研究和学习，也曾困扰过如何处理多个sheet，因此此处分享给大家，希望能有所帮助</p>\n<h2 id=\"1依赖\">1.依赖</h2>\n<p>首先需要导入EasyExcel依赖（lombok只是为了写实体类方便）</p>\n<pre><code>&lt;dependencies&gt;\n  <p>&lt;dependency&gt;\n    &lt;groupId&gt;org.projectlombok&lt;/groupId&gt;\n    &lt;artifactId&gt;lombok&lt;/artifactId&gt;\n    &lt;version&gt;1.18.34&lt;/version&gt;\n  &lt;/dependency&gt;</p>\n  <p>&lt;dependency&gt;\n    &lt;groupId&gt;com.alibaba&lt;/groupId&gt;\n    &lt;artifactId&gt;easyexcel&lt;/artifactId&gt;\n    &lt;version&gt;2.2.3&lt;/version&gt;\n  &lt;/dependency&gt;</p>\n<p>&lt;/dependencies&gt;</code></pre></p></p>\n<h2 id=\"2excel类\">2.Excel类</h2>\n<p>编写输出的Excel类，这里以Class类和Student类为例</p>\n<pre><code>@ToString\n@Data\n@AllArgsConstructor\n@NoArgsConstructor\npublic class Class {\n  @ExcelProperty(&quot;班级id&quot;)\n  private Integer id;\n  @ExcelProperty(&quot;班级名称&quot;)\n  private String name;\n}\n</code></pre>\n<pre><code>@ToString\n@Data\n@AllArgsConstructor\n@NoArgsConstructor\npublic class Student {\n  @ExcelProperty(&quot;班级id&quot;)\n  private Integer classId;\n  @ExcelProperty(&quot;学生id&quot;)\n  private Integer id;\n  @ExcelProperty(&quot;学生姓名&quot;)\n  private String name;\n}\n</code></pre>\n<h2 id=\"3处理excel读取和写入多个sheet\">3.处理Excel读取和写入多个sheet</h2>\n<p>通过注册监听器的方式处理数据的加载以及异常捕获等事件</p>\n<pre><code>@Slf4j\npublic class ExcelProcess {\n  public void read(File file) {\n    List&lt;Class&gt; classes = new ArrayList&lt;&gt;();\n    List&lt;Student&gt; students = new ArrayList&lt;&gt;();\n    try {\n      EasyExcel.read(file).sheet(0) //指定处理第一页sheet\n      .head(Class.class) // 指定Class类型\n      .registerReadListener(new ExcelReadListener&lt;Class&gt;(classes, file.getName())) //注册监听器，在监听器中进行进一步操作\n      .doRead();\n      EasyExcel.read(file).sheet(1)//指定处理第二页sheet\n      .head(Student.class)// 指定Student类型\n      .registerReadListener(new ExcelReadListener&lt;Student&gt;(students, file.getName()))//注册监听器，在监听器中进行进一步操作\n      .doRead();\n    } catch (Exception e) {\n      e.printStackTrace();\n    }\n    classes.forEach(System.out::println);\n    students.forEach(System.out::println);\n  }\n  public void write(File file) {\n    List&lt;Class&gt; classes = new ArrayList&lt;Class&gt;();\n    classes.add(new Class(1, &quot;1班&quot;));\n    classes.add(new Class(2, &quot;2班&quot;));\n    List&amp;lt;Student&amp;gt; students = new ArrayList&amp;lt;&amp;gt;();\n    students.add(new Student(1, 1, &quot;小明&quot;));\n    students.add(new Student(1, 2, &quot;小红&quot;));\n    students.add(new Student(2, 3, &quot;小黄&quot;));\n    students.add(new Student(2, 3, &quot;小蓝&quot;));\n    try {\n      writeExcel(file, &quot;excel名称&quot;, classes, students);\n    } catch (Exception e) {\n      log.error(&quot;写入excel失败&quot;, e);\n      throw e;\n    }\n  }\n  private void writeExcel(File file, String excelName, List... lists) {\n    ExcelWriter excelWriter = EasyExcel.write(file).build();\n    for (int i = 0; i &lt; lists.length; i++) {\n      WriteSheet writeSheet = EasyExcel.writerSheet(&quot;sheet&quot; + (i + 1))\n      .head(lists[i].get(0).getClass())\n      .build();\n      excelWriter.write(lists[i], writeSheet);\n    }\n    excelWriter.finish();\n  }\n  public static void main(String[] args) {\n    File file = new File(&quot;test.xlsx&quot;);\n    ExcelProcess excelProcess = new ExcelProcess();\n    excelProcess.write(file);\n    excelProcess.read(file);\n  }\n}</code></pre>\n<pre><code>@Slf4j\npublic class ExcelReadListener<T> extends AnalysisEventListener<T> {\n  private final List&lt;T&gt; dataList;\n  private String fileName;\n  public ExcelReadListener(List&lt;T&gt; dataList, String fileName) {\n    this.dataList = dataList;\n    this.fileName = fileName;\n  }\n  @Override\n  public void invoke(T t, AnalysisContext analysisContext) {\n    //将当前读取到的数据加入集合\n    dataList.add(t);\n  }\n  @Override\n  public void doAfterAllAnalysed(AnalysisContext analysisContext) {\n    log.info(&quot;Excel文件:&quot; + fileName + &quot; sheet:&quot; + analysisContext.getCurrentSheet().getSheetName() + &quot; 读取完成&quot;);\n  }\n  @Override\n  public void onException(Exception exception, AnalysisContext context) throws Exception {\n    if (exception instanceof ExcelDataConvertException) {\n        ExcelDataConvertException e = (ExcelDataConvertException) exception;\n        throw new RuntimeException(&quot;文件读取异常,sheet:&quot; + context.getCurrentSheet().getSheetName() +\n                &quot; 第&quot; + (e.getRowIndex() + 1) + &quot;行第&quot; + (char) (\'A\' + e.getColumnIndex()) + &quot;列出错，请修改后重新上传\\n&quot;\n                , e);\n    } else {\n        log.error(&quot;excel导入时出错&quot;);\n        throw new RuntimeException(&quot;系统异常，请重新上传&quot;, exception);\n    }\n  }\n}\n</code></pre>\n<h2 id=\"4-执行结果\">4. 执行结果</h2>\n<img src=\"https://xzf-blog.oss-cn-shanghai.aliyuncs.com/fd0e44def924418ab016eab8506337af.png\" alt=\"\">\n<img src=\"https://xzf-blog.oss-cn-shanghai.aliyuncs.com/5b6076d8d2cb49dfba10bdad5e53a453.png\" alt=\"\">\n<img src=\"https://xzf-blog.oss-cn-shanghai.aliyuncs.com/33d41077ab4e4d2d8ecda01a01206686.png\" alt=\"\">\n', '2026-01-24 04:00:22', '2026-02-03 01:16:25');
INSERT INTO `article_content` VALUES (20, 21, '<h1 id=\"一简介\">一.简介</h1>\n<p>MVCC（Multi-Version Concurrency Control）：多版本并发控制机制\n这是一种InnoDB引擎独有的一种控制事务隔离级别的机制，通过巧妙的设计处理写-读冲突，避免加锁造成的性能损耗，提高了数据库的并发性能。\n通过MVCC的机制读取数据我们称之为快照读（普通select...），以下介绍的主要是快照读逻辑。如果通过加锁（lock in share mode / for update）亦或是update修改数据等逻辑，那么走的是当前读逻辑，会通过加锁阻塞其他事物的操作，适合一致性要求较强的场景。</p>\n<h1 id=\"二适用场景\">二.适用场景</h1>\n<p>首先让我们先复习下数据库的四个隔离级别：</p>\n<pre><code>    \n  读未提交（Read uncommitted）\n  读已提交（Read committed）：解决脏读问题\n  可重复读（Repeatable read）：解决脏读和不可重复读问题\n  可串行化（Serializable）：解决脏读，不可重复读和幻读问题\n</code></pre>\n<p>在了解MVCC前，可能很多人（包括我）原本认为：\nmysql通过加上了写锁解决不可重复读的问题，在可重复读的隔离级别下，某个事务修改某一行的时候，其他事务无法对这一行数据进行修改和读取。\n这是错误的！\n事实上，四个隔离级别底层原理是这样实现的：\n读未提交（Read uncommitted）: 快照读：直接读  当前读：记录锁\n读已提交（Read committed）：快照读：mvcc  当前读：记录锁\n可重复读（Repeatable read）：快照读：mvcc  当前读：临界锁\n可串行化（Serializable）：都是临界锁\n也就是说，MVCC机制解决了原本我们以为必须要加写锁才能解决的并发问题，大大提升了数据库在并发情况下的性能。\n不过需要注意的是，写与写依旧是冲突的，InnoDB引擎无论在什么级别下，在修改数据前会添加记录锁或临界锁，确保其他事务只能对当前行数据进行读取而不能修改，完成数据修改后再释放排他锁。\n那么这么神奇的MVCC机制是如何实现的呢？</p>\n<h1 id=\"三实现原理\">三.实现原理</h1>\n<p>mvcc主要基于三大核心组件实现：隐藏字段（DB_TRX_ID + DB_ROLL_PTR） , undo log日志和Read View快照</p>\n<h2 id=\"31-隐藏字段\">3.1 隐藏字段</h2>\n<p>InnoDB引擎向数据库中的每一行添加了三个字段（使用者不可见）\nDB_TRX_ID：标识当前行内数据的唯一事务ID，每次修改或删除后对事务ID进行+1。\nDB_ROLL_PTR： 回滚指针，指向undo log中记录的上一个版本\nDB_ROW_ID： 众所周知，InnoDB引擎默认使用b+树作为存储的底层结构，而b+树是一种有序的数据结构。InnoDB引擎会默认将用户指定的主键设置为聚簇索引（b+树排序的根据），但如果没有设置主键，则将该字段设置为聚簇索引，与MVCC无关</p>\n<h2 id=\"32-undo-log日志\">3.2 undo log日志</h2>\n<p>undo log日志中会存储包含隐藏字段的历史版本\n例如，我们新建一个User表</p>\n<pre><code> \n  CREATE TABLE User(\n  id int PRIMARY KEY,\n  username VARCHAR(8)\n  );\ninsert into User VALUES (1,\'大黄\');\n</code></pre>\n<p>那么这个表的结构就是这样的（因为DB_ROW_ID与MVCC无关就省略了）\n因为此时DB_TRX_ID仅为1，不存在历史版本信息，因此undo log是空的，让我们修改该行数据</p>\n<pre><code> \nupdate User set username = \'小黑\' where id = 1;\n</code></pre>\n<p>修改数据后，DB_TRX_ID递增，DB_ROLL_PTR指向undo log中历史版本信息\n再次修改</p>\n<pre><code> \nupdate User set username = \'旺财\' where id = 1;\n</code></pre>\n<p>可以了解到DB_ROLL_PTR以一种链表的形式连接所有历史版本</p>\n<h2 id=\"33-read-view快照\">3.3 Read View快照</h2>\n<p>翻看源码，得知Read View的主要结构如下图所示（还有一些和视图相关的可能存在的字段，与MVCC核心实现相关不大，因此暂不概述）\n解释下各个字段的意义：\nm_low_limit_id：创建视图时还未被分配的最小事务ID，即最大活跃事务ID+1（高水位线）\nm_up_limit_id：创建视图时不包含自身的活跃事务列表中的最小事务ID（低水位线）\nm_creator_trx_id：申请创建视图的事务ID\nm_ids：创建视图时不包含自身的处于活跃的事务的ID集合\n小小吐槽一下，这个low和up真的没有命名反吗？\n而在不同隔离级别下，创建Read View快照的策略有所不同：\n读已提交：每次事务发起select查询语句时创建快照\n可重复读：只有当前事务第一次发起select查询语句时创建快照\n让我们举个例子：\n当事务2第一次发起select查询时，只有事务1已经提交，而事务3，4已经开启，因此：\nm_low_limit_id（最大活跃事务ID+1）= 5\nm_up_limit_id（最小活跃事务ID，不包含自身）= 3\nm_creator_trx_id（发起创建快照的当前事务ID）= 2\nm_ids（当前活跃事务ID集合，不包含自身）= {3，4}\n如果是读已提交级别，那么当事务2第二次发起select查询时，则会创建新的Read View快照,此时事务3已经提交：\nm_low_limit_id（最大活跃事务ID+1）= 5\nm_up_limit_id（最小活跃事务ID，不包含自身）= 4\nm_creator_trx_id（发起创建快照的当前事务ID）= 2\nm_ids（当前活跃事务ID集合，不包含自身）= {4}</p>\n<h2 id=\"34-可见性逻辑\">3.4 可见性逻辑</h2>\n<p>MVCC实质上是综合以上结构，使用视图判断当前行数据是否可见来处理写读冲突，如果不可见，则会通过回滚指针回滚到历史版本再次进行可见性判断，直到找到第一个可见的历史版本返回，即为select查询到的数据，实现了读已提交和可重复读的隔离级别。\n翻看源码可以得知，核心判断可见性逻辑是由该方法实现：</p>\n<pre><code> \n  /** Check whether the changes by id are visible.\n  @param[in]    id      transaction id to check against the view\n  @param[in]    name    table name\n  @return whether the view sees the modifications of id. */\n  [[nodiscard]] bool changes_visible(trx_id_t id,\n  const table_name_t &amp;name) const {\n  ut_ad(id &gt; 0);\n  if (id &lt; m_up_limit_id || id == m_creator_trx_id) {\n    return (true);\n  }\n  check_trx_id_sanity(id, name);\n  if (id &gt;= m_low_limit_id) {\n    return (false);\n  } else if (m_ids.empty()) {\n    return (true);\n  }\n  const ids_t::value_type *p = m_ids.data();</p>\n    return (!std::binary_search(p, p + m_ids.size(), id));\n  }\n</code></pre>\n<p>让我们逐行解释：\n入参：\nid：要检查的事务 ID。\nname：当前操作涉及的表名，用于在检查事务 ID 时确保上下文正确。\n逻辑说明：</p></p>\n<p>ut_ad(id &gt; 0)：进行断言检查，确保传入的 id 参数大于 0。</p>\n<p>if (id &lt; m_up_limit_id || id == m_creator_trx_id)：</p>\n<p>如果要检查的事务 ID 小于最小活跃事务 ID 或等于当前事务 ID，则可见，返回 true。\ncheck_trx_id_sanity(id, name)：验证该事务 ID 是否与指定表 (name) 的状态一致。</p>\nif (id &gt;= m_low_limit_id)：\n如果要检查的事务 ID 大于等于最小未被分配的事务 ID（当前最大事务 ID + 1），那么一定不可见，返回 false。\nelse if (m_ids.empty())：\n在要检查的事务 ID 小于最小未被分配的事务 ID 的基础上，如果当前活跃事务集合为空，那么一定可见，返回 true。\nconst ids_t::value_type *p = m_ids.data();\nreturn (!std::binary_search(p, p + m_ids.size(), id))：\n二分查找当前活跃事务集合中是否存在要检查的事务 ID。如果不存在，则可见，返回 true；如果存在，则不可见，返回 false。\n让我们再拿先前的例子开始讲解：\n如果事务隔离级别为可重复读，那么第二次查询时可见数据仍然为事务ID=2的数据，实现了可重复读\n如果为读已提交，则会重新创建一份视图快照：\n至于其他一些情况，我就不带着大家一起枚举或者进行数学逻辑上的验证了，感兴趣的小伙伴们可以自己尝试下。\nMVCC便是通过上述结构，将可见性的问题进行层层分离，只使用了一些简单的逻辑判断便解决了事务的隔离级别和读-写冲突问题，让人不得不佩服制作者的巧思。\n由此，我们就理解了MVCC是如何巧妙地处理了写-读冲突，实现了读已提交和可重复读的隔离级别。不过对于串行的隔离级别来说，我们就不得不加上间隙锁实现一个表锁的功能了。\n四.总结\nInnoDB引擎通过MVCC机制，巧妙地解决了并发场景下的写-读冲突。了解了MVCC的核心原理，对于以后我们自己设计一些高并发下调优的架构也有所帮助。\n', '2026-01-31 23:06:04', '2026-02-07 02:57:44');
INSERT INTO `article_content` VALUES (21, 22, '<p>#开启\n#关闭\n#重启\n./root/zookeeper/zookeeperCluster.sh start\n./root/zookeeper/zookeeperCluster.sh stop\n./root/zookeeper/zookeeperCluster.sh restart</p>\n<p>读者也可以自己修改脚本内容尝试添加更多参数与命令</p>\n', '2026-02-03 01:53:25', '2026-02-07 02:57:41');
INSERT INTO `article_content` VALUES (22, 23, '<p>在多线程场景下，最经典的两个锁无疑分别是synchronized和ReentranLock，本文中我们将深入了解synchronized底层如何实现</p>\n<p>目录</p>\n<p>一. 简介</p>\n<p>二. 基本使用方式</p>\n<pre><code>    2.1 同步方法\n<pre><code>2.2 同步代码块\n</code></pre>\n<p></code></pre></p>\n<p>三. 锁升级</p>\n<p>四. 实现原理</p>\n<p>一. 简介\n由于不同的硬件和不同的操作系统在内存上的操作有一定差异的，因此Java通过定义了一套规范-----JMM来屏蔽掉各种硬件和操作系统带来的差异，让Java的并发编程做到跨平台。</p>\n<pre><code>    而JMM主要基于三大特性保证线程安全：\n<pre><code>· 原子性：指一个操作是不可分割，不可中断的，一个线程无法影响到另一个线程的原子操作\n<p>· 有序性：JVM具体在执行.class文件时，为了提升运行效率，实际上会在不影响最终结果的情况下，对里面的指令进行乱序执行，发挥CPU的性能，而有序性则是避免指令重排</p>\n<p>· 可见性：主流操作系统中，每个CPU和主内存之间存在着三级缓存提升获取数据效率，但是在多核CPU执行多线程情况下，可能会出现一个线程操作完该CPU的缓存数据，没有及时同步到主内存时，另一个CPU就操作了它自己的缓存数据。而为了避免这一点，可见性会告诉所有对当前资源的操作，不允许使用CPU缓存，必须和主内存交互</p>\n<p>synchronized便是保证原子性、有序性、可见性的常规实现方式之一。\n</code></pre></p>\n<p></code></pre></p>\n<p>二. 基本使用方式\n2.1 同步方法\n只需要在方法名上添加synchronized修饰符即可保证该方法的线程安全</p>\n  不过需要注意的是，下列两种情况有所不同：\n<pre><code>  \npublic synchronized void print(){ ... }\n</code></pre>\n<p>\npublic static synchronized void print(){ ... }\nAI写代码\n在静态方法中，会以类的字节码作为锁对象，无论是哪个对象，或者通过 类名.方法名 调用synchronized修饰的静态方法，都能保证线程安全。</p>\n而在非静态方法中，会以类的对象作为锁对象。如果同一对象调用synchronized修饰的非静态方法，那么能保证线程安全；如果不同对象调用synchronized修饰的非静态方法，实质上是相互隔离的，可能会让错误使用的编程者留下线程不安全的隐患。\n<pre><code>2.2 同步代码块\n同步代码块的使用方法比较容易理解，它需要显示指定锁对象\n</code></pre>\n<pre><code>  \npublic  void print(){\n    synchronized (this.getClass()){\n      //...\n    }\n}\n</code></pre>\n<p>不过需要注意的是，尽管Java底层对于synchronized有着锁消除和锁膨胀的优化方案，却没有锁缩减的优化方案，因此我们在锁的粒度上需要多加思考，提高程序的性能。</p>\n<p>三. 锁升级\n需要注意的是，由于jdk1.5中的synchronized效率低下，被Doug Lea大佬一顿狂批，并写出了AQS让Oracle官方不得不服气，因此Oracle官方在jdk1.6中对synchronized模仿AQS进行大量优化，可以说是面貌全非。而本文中讲解的是jdk1.8，即Oracle官方优化后的synchronized版本。\n<pre><code>    synchronized的优化主要基于锁升级的概念，以下是synchronized的四种状态：\n<pre><code>无锁：当前对象没有锁存在\n<p>偏向锁：如果当前仅有一个线程在频繁地尝试获取和释放锁，那么只需要判断之前获取锁的是不是当前线程。如果是，那么直接获取锁；如果不是，基于CAS（一种CPU原子操作）方式尝试获取锁，获取不到则升级成轻量级锁</p>\n<p>轻量级锁：采用自旋锁的方式尝试获取锁。自旋一定次数后仍获取不到，则升级成重量级锁</p>\n<p>重量级锁：拿不到锁资源，就挂起当前线程（转换成用户态），底层由C++语言编写。\n</code></pre></p>\n<p></code></pre>\n锁升级流程：\n需要注意的是,synchronized只有锁升级的概念，并没有锁降级的概念。</p>\n<p>四. 实现原理\n由于各个版本的虚拟机实现方式可能不同，本文仅讲解oracle官方的虚拟机--&gt;Hotspot虚拟机下的实现原理</p>\n首先让我们回顾下在堆中存储的对象的内存布局：\n<pre><code>（即便锁的是类.class，比如静态方法，实际锁的是堆中存储的对应的与该类相关联的Class对象，仍然具备对象的内存布局）\n</code></pre>\n<p>而synchronized的实现便与对象头中的MarkWord密不可分，让我们展开MarkWord</p>\n<pre><code>可以看到MarkWord的64个bit位，会根据锁状态的变化有所不同，挑几个重点讲解一下：\n<p>锁标志位：通过2位表示锁的状态（0代表没有上锁，1代表上锁）</p>\n<p>偏向锁位：表示是否上锁(CAS修改位置)</p>\n<p>线程指针：指向当前获取锁，或者当前没有线程获取锁状态下上一个获取锁的线程\nLock Record：每个线程栈独有的存储锁信息的一种数据结构，通常包含：当前线程的线程指针、自旋锁记录、锁对象的信息（即将原先无锁/偏向锁状态下存储的信息移到Lock Record中）。\n不过轻量级锁有一点需要注意的是，synchronized从偏向锁升级到轻量级锁时，会涉及到偏向锁撤销，需要到达下一个安全点STW（STOP THE WORLD）才能进行。因为JVM在启动时需要加载大量字节码文件到内存，JVM默认采取了偏向锁延迟4s开启的优化策略：即在启动4s内为无锁状态，然后会升级成匿名偏向锁。\n虽然在偏向锁状态下,线程指针指向的是当前获取锁的线程，但是此时仍然存在Lock Record，只是相较轻量级锁状态下的Lock Record存储的信息少了一些。</p>\n<p>可以说偏向锁和轻量级锁获取锁的本质，就是让对象的MarkWord中的指针指向当前线程或当前线程的Lock Record。</p>\n<p>而重量级锁则是运用了C++语言编写的Object Manager存储排队的线程等进行操作。</p>\n<p>通过锁升级的机制，synchronized有效避免了一些线程争抢不激烈情况下，对于线程状态切换的资源消耗 。但是对于一些可以预见的线程争抢激烈的情况，synchronized却仍然要经历一个锁升级的步骤才能将线程挂起，可以说是得不偿失，因此我们可以用AQS锁替代（常见实现有ReentrantLock等）。</p>\n<p>获取锁流程：</p>\n<p>无锁状态：有线程获取锁，升级偏向锁</p>\n<p>偏向锁状态：判断偏向锁位是否为1（是否上锁）</p>\n<pre><code>    如果为1，判断MarkWord中的指针是否指向当前试图获取锁的线程（可重入），是则获取成功；不是则获取失败，升级轻量级锁\n<pre><code>如果为0，尝试基于CAS将其修改为1，修改成功则成功获取锁，将线程指针指向当前线程；获取失败则获取失败，升级轻量级锁\n</code></pre>\n<p></code></pre></p>\n<p>轻量级锁：判断MarkWord中的指针是否指向当前线程的Lock Record</p>\n<pre><code>    是则获取成功（可重入）\n<pre><code>不是则尝试一定次数的自旋操作，基于CAS获取锁（修改Lock Record中的锁状态），如果修改成功则成功获取锁，将指针指向当前线程的Lock Record，多次自旋都失败后升级重量级锁\n</code></pre>\n<p></code></pre></p>\n<p>重量级锁：基于C++的Object Manager对线程状态进行控制</p>\n<p>本文到此结束了，希望能对大家理解多线程有所帮助\n</code></pre></p>\n<p></code></pre></p>\n', '2026-02-03 01:55:04', '2026-02-08 20:58:08');
INSERT INTO `article_content` VALUES (23, 24, '<p>一、问题描述\n在测试接口的时候遇到以下问题：</p>\n<pre><code>    后台报错：\n</code></pre>\n<p>2024-08-10T01:53:38.750+08:00  WARN 6344 --- [nio-8080-exec-3] .w.s.m.s.DefaultHandlerExceptionResolver : Resolved [org.springframework.web.method.annotation.MethodArgumentTypeMismatchException: Failed to convert value of type \'java.lang.String\' to required type \'com.haishi.test.model.enums.ItemType\'; Failed to convert from type [java.lang.String] to type [@org.springframework.web.bind.annotation.RequestParam com.haishi.test.model.enums.ItemType] for value \'1\']\nAI写代码\njava\n运行\ncontroller层执行的代码：</p>\n<pre><code>@Operation(summary = &quot;[根据类型]查询配套信息列表&quot;)\n@GetMapping(&quot;list&quot;)\npublic Result&lt;List&lt;FacilityInfo&gt;&gt; listFacility(@RequestParam(required = false) ItemType type) {\n    LambdaQueryWrapper&lt;FacilityInfo&gt; queryWrapper = new LambdaQueryWrapper();\n    if (type != null) {\n        queryWrapper.eq(FacilityInfo::getType, type);\n    }\n    List&lt;FacilityInfo&gt; list = facilityInfoService.list(queryWrapper);\n    return Result.ok(list);\n}\n</code></pre>\n<p>AI写代码\njava\n运行</p>\n<p>二、项目概述\n2.1 依赖\n常见的SpringBoot+web+mybatis-plus+mysql+lombok+knife4j(测试方便)。</p>\n<pre><code>            这里尽量使用mybatis-plus而不是mybatis，详细原因之后会解释。\n</code></pre>\n<!-- 继承Spring Boot父项目 -->\n<pre><code>&lt;parent&gt;\n    &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;\n    &lt;artifactId&gt;spring-boot-starter-parent&lt;/artifactId&gt;\n    &lt;version&gt;3.0.5&lt;/version&gt;\n&lt;/parent&gt;\n<p>&lt;dependencies&gt;\n&lt;!--包含spring web相关依赖--&gt;\n&lt;dependency&gt;\n&lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;\n&lt;artifactId&gt;spring-boot-starter-web&lt;/artifactId&gt;\n&lt;/dependency&gt;</p>\n<pre><code>&amp;lt;!--包含spring test相关依赖--&amp;gt;\n&amp;lt;dependency&amp;gt;\n    &amp;lt;groupId&amp;gt;org.springframework.boot&amp;lt;/groupId&amp;gt;\n    &amp;lt;artifactId&amp;gt;spring-boot-starter-test&amp;lt;/artifactId&amp;gt;\n    &amp;lt;scope&amp;gt;test&amp;lt;/scope&amp;gt;\n&amp;lt;/dependency&amp;gt;\n<p>&amp;lt;dependency&amp;gt;\n&amp;lt;groupId&amp;gt;com.github.xiaoymin&amp;lt;/groupId&amp;gt;\n&amp;lt;artifactId&amp;gt;knife4j-openapi3-jakarta-spring-boot-starter&amp;lt;/artifactId&amp;gt;\n&amp;lt;version&amp;gt;4.1.0&amp;lt;/version&amp;gt;\n&amp;lt;/dependency&amp;gt;</p>\n<p>&amp;lt;!--mybatis-plus--&amp;gt;\n&amp;lt;dependency&amp;gt;\n&amp;lt;groupId&amp;gt;com.baomidou&amp;lt;/groupId&amp;gt;\n&amp;lt;artifactId&amp;gt;mybatis-plus-boot-starter&amp;lt;/artifactId&amp;gt;\n&amp;lt;version&amp;gt;3.5.3.1&amp;lt;/version&amp;gt;\n&amp;lt;/dependency&amp;gt;</p>\n<p>&amp;lt;!--mysql驱动--&amp;gt;\n&amp;lt;dependency&amp;gt;\n&amp;lt;groupId&amp;gt;com.mysql&amp;lt;/groupId&amp;gt;\n&amp;lt;artifactId&amp;gt;mysql-connector-j&amp;lt;/artifactId&amp;gt;\n&amp;lt;/dependency&amp;gt;\n&amp;lt;dependency&amp;gt;\n&amp;lt;groupId&amp;gt;org.projectlombok&amp;lt;/groupId&amp;gt;\n&amp;lt;artifactId&amp;gt;lombok&amp;lt;/artifactId&amp;gt;\n&amp;lt;version&amp;gt;1.18.26&amp;lt;/version&amp;gt;\n&amp;lt;scope&amp;gt;provided&amp;lt;/scope&amp;gt;\n&amp;lt;/dependency&amp;gt;</p>\n<p>&amp;lt;dependency&amp;gt;\n&amp;lt;groupId&amp;gt;org.projectlombok&amp;lt;/groupId&amp;gt;\n&amp;lt;artifactId&amp;gt;lombok&amp;lt;/artifactId&amp;gt;\n&amp;lt;/dependency&amp;gt;\n</code></pre></p>\n<p>&lt;/dependencies&gt;\n</code></pre></p>\n<p>AI写代码\nXML</p>\n<pre><code>    2.2 项目思路\n    首先让我们来看下数据库\n<pre><code>可以看到在数据库中，type字段的存储类型是tinyint，用1和2来区分类型（前端接受的数据类型与数据库一致）。数据库设计需要极致地压缩空间，需要采用tinyint，但是在我们编写后端程序的时候容易逻辑紊乱，特别是团队开发的时候。故此在JAVA程序中使用enum类进行区分是一种规范的操作。\n<p>对应的实体类FacilityInfo:\n</code></pre></p>\n<p></code></pre></p>\n<p>@Schema(description = &quot;配套信息表&quot;)\n@TableName(value = &quot;facility_info&quot;)\n@Data\npublic class FacilityInfo extends BaseEntity {\nprivate static final long serialVersionUID = 1L;</p>\n<pre><code>@Schema(description = &quot;配套所属对象类型&quot;)\n@TableField(value = &quot;type&quot;)\nprivate ItemType type;\n<p>@Schema(description = &quot;名称&quot;)\n@TableField(value = &quot;name&quot;)\nprivate String name;</p>\n<p>@Schema(description = &quot;图标&quot;)\n@TableField(value = &quot;icon&quot;)\nprivate String icon;\n</code></pre></p>\n<p>}\nAI写代码\njava\n运行</p>\n<pre><code>    先看下所有enum类的接口BaseEnum（后续会解释为什么需要这个接口）：\n</code></pre>\n<p>public interface BaseEnum {</p>\n<pre><code>Integer getCode();\n<p>String getName();\n</code></pre></p>\n<p>}\nAI写代码\njava\n运行\n然后是type字段对应的ItemType枚举类：</p>\n<p>public enum ItemType implements BaseEnum {</p>\n<pre><code>APARTMENT(1, &quot;公寓&quot;),\n<p>ROOM(2, &quot;房间&quot;);</p>\n<p>private Integer code;\nprivate String name;</p>\n<p>@Override\npublic Integer getCode() {\nreturn this.code;\n}</p>\n<p>@Override\npublic String getName() {\nreturn name;\n}</p>\n<p>ItemType(Integer code, String name) {\nthis.code = code;\nthis.name = name;\n}\n</code></pre></p>\n<p>}\nAI写代码\njava\n运行</p>\n<pre><code>    即在前端和数据库中的&quot;1&quot;对应后端的ItemType.APARTMENT,&quot;0&quot;则对应ItemType.ROOM。\n</code></pre>\n<p>三、问题分析\n从异常名称分析这是一个类型转换失败导致的异常，那么首先让我们从头到尾了解一下数据是如何在前端发送至数据库，或者从数据库发送至前端的过程中进行类型转换的。</p>\n<pre><code>    从上图中我们可以分析出问题主要可能出在WebDataBinder组件，TypeHandler和HTTPMessageConverter上，接下来让我们一一分析。\n<pre><code>3.1 WebDataBinder问题分析\n        WebDataBinder组件主要的作用是将HTTP的请求参数绑定到Controller方法的参数，并实现参数类型的转换。\n<pre><code>    很容易猜到的是，这里的问题是从数值类型到枚举类型的转换发生异常。\n<pre><code>WebDataBinder依赖于Converter进行转换，其中虽然有默认常用转换规则的存在，但很明显在此处发生了异常，后台系统发生的异常也是由它抛出。\n<p>默认转换规则中提供了一个String类型到枚举类型的转换规则，根据实例名称到枚举对象实例进行转换，例如可以将一个&amp;amp;amp;quot;APARTMENT&amp;amp;amp;quot;转换为ItemType.APARTMENT，并不适用于当下这种情况，需要自定义Converter做到图中的功能。\n</code></pre></p>\n<p></code></pre></p>\n<p>3.2 TypeHandler  问题分析\nMybatis中的TypeHandler用于处理Java的实体对象与数据库之间的数据类型转换</p>\n<pre><code>    与WebDataBinder的默认转换规则相似，不能支持此处场景下的枚举类型和数值类型的转换，需要自定义TypeHandler，否则会发生异常。\n</code></pre>\n<p>3.3 HTTPMessageConverter 问题分析\n</code></pre></p>\n<p>HTTPMessageConverter组件负责将Controller方法的返回值转换为HTTP响应体中的JSON字符串，或者反之。</p>\n<pre><code>        默认规则与前两者相同，不支持此种类型转换，需要自定义转换规则。\n<pre><code>    但与前两者不同的是，由于本项目中HTTPMessageConverter组件只负责将方法返回值转换为响应体字符串，因此如果没有自定义规则，不会报异常，但是前端接受的数据则为&amp;amp;quot;type&amp;amp;quot;:&amp;amp;quot;APARTMENT&amp;amp;quot;，需要注意检查。\n</code></pre>\n<p></code></pre></p>\n<p></code></pre></p>\n<p>四、解决问题\n从问题分析中我们得知，这里虽然只会出现一个报错信息，但想要枚举类类型能够按我们所要求的那样在程序中正常地进行类型转换，我们需要解决三个问题。</p>\n<pre><code>    4.1 WebDataBinder类型转换\n            既然SpringMVC中的WebDataBinder组件自带的类型转换器无法处理从数字字符串到ItemType类型的转换，那么我们需要手动添加Converter，告诉WebDataBinder组件如何处理源类型到目标类型的转换。\n<pre><code>        首先，我们通过实现Spring框架提供的Converter&amp;lt;S,T&amp;gt;接口来编写一个Converter转换器\n</code></pre>\n<p></code></pre></p>\n<p>@Component\npublic class StringToItemTypeConverter implements Converter&lt;String, ItemType&gt; {\n@Override\npublic ItemType convert(String source) {</p>\n<pre><code>    ItemType[] values = ItemType.class.getEnumConstants();\n    for (ItemType itemType : values) {\n        if (itemType.getCode().equals(Integer.valueOf(source))) {\n            return itemType;\n        }\n    }\n<pre><code>throw new IllegalArgumentException(&amp;quot;code:&amp;quot;+source+&amp;quot;非法&amp;quot;);\n</code></pre>\n<p>}\n</code></pre></p>\n<p>}\nAI写代码\njava\n运行</p>\n<pre><code>           拓展：\n<pre><code>        当我们有多个枚举类需要编写Converter转换器，那么一个个地去编写转换器无疑过于繁琐，我们则可以通过编写一个ConverterFactory来一劳永逸的解决。\n<pre><code>    我们可以看到，目标类型T必须是传入类型或其父类，因此此处使用前面提到的所有枚举类的接口BaseEnum，就能解决所有枚举类的类型Converter转换问题了。\n</code></pre>\n<p></code></pre></p>\n<p></code></pre></p>\n<p>@Component\npublic class StringToBaseEnumConverterFactory implements ConverterFactory&lt;String, BaseEnum&gt; {\n@Override\npublic <T extends BaseEnum> Converter&lt;String, T&gt; getConverter(Class<T> targetType) {\nreturn new Converter&lt;String, T&gt;() {\n@Override\npublic T convert(String source) {</p>\n<pre><code>            T[] values = targetType.getEnumConstants();\n            for (T t : values) {\n                if (t.getCode().equals(Integer.valueOf(source))) {\n                    return t;\n                }\n            }\n            throw new IllegalArgumentException(&quot;非法的枚举值:&quot;+source);\n        }\n    };\n}\n</code></pre>\n<p>}\nAI写代码\njava\n运行</p>\n<pre><code>    然后向通过Configuration向WebDataBinder组件注册该Converter或ConverterFactory即可\n</code></pre>\n<p>@Configuration\npublic class WebMvcConfiguration implements WebMvcConfigurer {</p>\n<pre><code>@Autowired\nprivate StringToBaseEnumConverterFactory factory;\n<p>@Autowired\nprivate StringToItemTypeConverter converter;</p>\n<p>@Override\npublic void addFormatters(FormatterRegistry registry) {\n</code></pre></p>\n<p>//        registry.addConverter(this.converter);\nregistry.addConverterFactory(this.factory);\n}\n}\nAI写代码\njava\n运行</p>\n<pre><code>    4.2 TypeHandler类型转换\n            与WebDataBinder类似，TypeHandler需要自定义如何进行类型转换。\n<pre><code>        如果使用的是mybatis，那么我们必须要手动编写一个TypeHandler类。不过mybatis-plus则提供了一个通用的处理枚举类型的TypeHandler,只需要在ItemType中添加一个@EnumValue注解，mybatis-plus就可以自动完成从ItemType类型到code属性的相互映射。\n</code></pre>\n<p>@EnumValue\nprivate Integer code;\n</code></pre></p>\n<p>AI写代码\njava\n运行\n4.3 HTTPMessageConverter 类型转换\n与TypeHandler相同，其提供了一个注解@JsonValue,使用该注解Jackson就可以自动完成从ItemType类型到code属性的相互映射。官方文档</p>\n<pre><code>@EnumValue\n@JsonValue\nprivate Integer code;\n</code></pre>\n<p>五、总结\nMVC框架自带的类型转换功能有时候并不能满足我们的需求，这时候我们就需要手动添加响应的类型转换功能。虽然问题有时候看起来会无从下手，但冷静下来仔细分析，逐步排查可能的原因，就能找到正确的解决办法。</p>\n', '2026-02-03 01:57:00', '2026-02-08 20:57:54');
INSERT INTO `article_content` VALUES (24, 25, '<p>最近在学习SpringCloud，对于LoadBalancer有所好奇，于是就深挖了一些底层原理。</p>\n<h1 id=\"loadbalancer概述\">LoadBalancer概述</h1>\n<p>Spring Cloud LoadBalancer是由SpringCloud官方提供的一个开源的、简单易用的客户端负载均衡器。官方文档</p>\n相对于Nginx来说，LoadBalancer的特点在于其客户端负载均衡，它会向注册中心获取注册信息列表后，缓存到JVM中，通过轮询算法选择调用的服务端发送请求。\n而Nginx则是服务器端负载均衡，客户端所有的请求都会交给Nginx，由Nginx实现服务端的选择，以及转发请求。\nLoadBalancer具体的负载均衡实现逻辑在ReactorServiceInstanceLoadBalancer实现类中，常见的有三个：RoundRobinLoadBalancer，RandomLoadBalancer和NacosLoadBalancer。\nReactorServiceInstanceLoadBalancer的一些通用属性：\nserviceId:服务的唯一标识，用于指定当前负载均衡器所要操作的服务。\nserviceInstanceListSupplierProvider;提供服务实例列表的供应者，用于在负载均衡时提供该服务的所有可用实例。\nRoundRobinLoadBalancer（Consul默认）\n2.1 依赖版本\n不同版本的源码可能有所不同</p>\n<pre><code> &lt;!--loadbalancer--&gt;\n &lt;dependency&gt;\n     &lt;groupId&gt;org.springframework.cloud&lt;/groupId&gt;\n     &lt;artifactId&gt;spring-cloud-starter-loadbalancer&lt;/artifactId&gt;\n     &lt;version&gt;4.0.4&lt;/version&gt;\n &lt;/dependency&gt;\n</code></pre>\n<p>在这个包下面一共有两种负载均衡算法的实现类：RoundRobinLoadBalancer和RandomLoadBalancer</p>\n<h2 id=\"22-源码\">2.2 源码</h2>\n<p>LoadBalancer（consul为注册中心）默认使用的是RoundRobinLoadBalancer类\n提取了一些实现负载均衡核心逻辑的代码</p>\n<pre><code>\npublic Mono&lt;Response&lt;ServiceInstance&gt;&gt; choose(Request request) {\n    ServiceInstanceListSupplier supplier = (ServiceInstanceListSupplier)this.serviceInstanceListSupplierProvider.getIfAvailable(NoopServiceInstanceListSupplier::new);\n    return supplier.get(request).next().map((serviceInstances) -&gt; {\n        return this.processInstanceResponse(supplier, serviceInstances);\n    });\n}\nprivate Response&lt;ServiceInstance&gt; getInstanceResponse(List&lt;ServiceInstance&gt; instances) {\n    if (instances.isEmpty()) {\n        if (log.isWarnEnabled()) {\n            log.warn(&quot;No servers available for service: &quot; + this.serviceId);\n        }\n<pre><code>    return new EmptyResponse();\n} else if (instances.size() == 1) {\n    return new DefaultResponse((ServiceInstance)instances.get(0));\n} else {\n    int pos = this.position.incrementAndGet() &amp;amp; Integer.MAX_VALUE;\n    ServiceInstance instance = (ServiceInstance)instances.get(pos % instances.size());\n    return new DefaultResponse(instance);\n}\n</code></pre>\n<p>}\n</code></pre></p>\n<p>choose方法：实现了负载均衡的核心逻辑\nserviceInstanceListSupplierProvider.getIfAvailable：获取一个 实例，该实例提供服务实例的列表--&gt;哪些生产者能够提供服务。\nsupplier.get(request).next()：获取下一个可用的服务实例。\nmap 操作：使用响应式编程的方式，异步通过getInstanceResponse方法处理返回的服务实例列表，选择下一个选择的合适的服务实例（负载均衡）\ngetInstanceResponse方法：实现了负载均衡的核心算法：轮询算法</p>\n如果 instances 为空，返回 EmptyResponse。\n如果 instances 只有一个，直接返回该实例。\n如果有多个实例：\nthis.position.incrementAndGet() &amp; Integer.MAX_VALUE：对 position 计数器执行递增操作，然后使用 &amp; Integer.MAX_VALUE 来确保值为非负整数。\npos % instances.size()：使用模运算来选择当前轮询到的服务实例</p>\n<h2 id=\"23-解析\">2.3 解析</h2>\n<p>总结一下：装载了LoadBalancer的消费者客户端会先向服务注册中心注册服务，并获取生产者服务列表，然后会由LoadBalancer通过轮询算法选取合适的提供服务的生产者，并发送请求。</p>\n<pre><code>轮询算法：请求数%服务器总集群数=实际调用服务器位置下标。每次服务重启请求数重新从1开始。\n<p>例如上图的集群（集群数为3）：</p>\n<p>第一次请求： 1%3=1  则请求生产者1</p>\n<p>第二次请求： 2%3=2  请求生产者2</p>\n<p>第三次请求： 3%3=3  请求生产者0</p>\n<p>以此类推\n</code></pre></p>\n<p>NacosLoadBalancer(Nacos默认)\n如果你是使用Nacos的用户，它自定义了一个NacosLoadBalancer的负载均衡算法，也是其默认算法。</p>\n<h2 id=\"31-依赖版本\">3.1 依赖版本</h2>\n<p>虽然名为NacosLoadBalancer，但它却是在nacos包下的，和其他两个不同，它不在LoadBalancer依赖中。但是，如果你想要使用负载均衡的话，还是必须得引入LoadBalancer依赖以提供一些其余组件。</p>\n<pre><code>     &lt;dependency&gt;\n         &lt;groupId&gt;com.alibaba.cloud&lt;/groupId&gt;\n         &lt;artifactId&gt;spring-cloud-starter-alibaba-nacos-discovery&lt;/artifactId&gt;\n         &lt;version&gt;2022.0.0.0-RC2&lt;/version&gt;\n     &lt;/dependency&gt;\n</code></pre>\n<h2 id=\"32-源码\">3.2 源码</h2>\n<pre><code>\npublic Mono&lt;Response<ServiceInstance>&gt; choose(Request request) {\nServiceInstanceListSupplier supplier = (ServiceInstanceListSupplier)this.serviceInstanceListSupplierProvider.getIfAvailable(NoopServiceInstanceListSupplier::new);\nreturn supplier.get(request).next().map(this::getInstanceResponse);\n}</p>\nprivate Response&lt;ServiceInstance&gt; getInstanceResponse(List&lt;ServiceInstance&gt; serviceInstances) {\n    if (serviceInstances.isEmpty()) {\n        log.warn(&quot;No servers available for service: &quot; + this.serviceId);\n        return new EmptyResponse();\n    } else {\n        try {\n            String clusterName = this.nacosDiscoveryProperties.getClusterName();\n            List&lt;ServiceInstance&gt; instancesToChoose = serviceInstances;\n            if (StringUtils.isNotBlank(clusterName)) {\n                List&lt;ServiceInstance&gt; sameClusterInstances = (List)serviceInstances.stream().filter((serviceInstance) -&gt; {\n                    String cluster = (String)serviceInstance.getMetadata().get(&quot;nacos.cluster&quot;);\n                    return StringUtils.equals(cluster, clusterName);\n                }).collect(Collectors.toList());\n                if (!CollectionUtils.isEmpty(sameClusterInstances)) {\n                    instancesToChoose = sameClusterInstances;\n                }\n            } else {\n                log.warn(&quot;A cross-cluster call occurs，name = {}, clusterName = {}, instance = {}&quot;, new Object[]{this.serviceId, clusterName, serviceInstances});\n            }\n<pre><code>        instancesToChoose = this.filterInstanceByIpType(instancesToChoose);\n        ServiceInstance instance = NacosBalancer.getHostByRandomWeight3(instancesToChoose);\n        return new DefaultResponse(instance);\n    } catch (Exception var5) {\n        Exception e = var5;\n        log.warn(&amp;quot;NacosLoadBalancer error&amp;quot;, e);\n        return null;\n    }\n}\n</code></pre>\n<p>}</p>\n<p>主要关注与RoundRobinLoadBalancer不同的实现部分\n集群不为空时：\nserviceInstances.stream().filter(...): 使用流操作过滤出与当前集群名称匹配的服务实例。\nserviceInstance.getMetadata().get(&quot;nacos.cluster&quot;): 从服务实例的元数据中获取其所属的集群名称。\nStringUtils.equals(cluster, clusterName): 判断实例的集群名称是否与当前集群名称相同。\n.collect(Collectors.toList()): 将过滤后的实例收集成列表 sameClusterInstances。\n.filterInstanceByIpType:根据IP类型过滤实例\n重点：从集群中选择合适服务的方法为：NacosBalancer.getHostByRandomWeight3()\n这是一个包装的非常重量级的算法：加权随机算法，这里就不展开了（从方法名可知这个方法被调用的是第三层），感兴趣的朋友们自己学习一下源码吧。\n原理：\n计算服务列表的总权重\n生成一个【0，总权重）的随机数\n遍历实例列表，累加实例权重，当累加值首次超过随机数r时，选择当前实例</p>\n<h2 id=\"33-解析\">3.3 解析</h2>\n<p>负载均衡算法：加权随机算法</p>\n<pre><code>总权重： 5 + 3 + 7 =15\n<p>因此每次请求时：</p>\n<p>请求生产者0的概率为： 15 / 5</p>\n<p>请求生产者1的概率为： 15 / 3</p>\n<p>请求生产者2的概率为： 15 / 7</p>\n<p>若第一次请求，随机数为5 :选择生产者1</p>\n<p>若第二次请求，随机数为14 :选择生产者2</p>\n<p>若第三次请求，随机数为4 :选择生产者0\n</code></pre></p>\n<p>修改默认算法\n如果我们偶尔不满意于LoadBalancer默认的轮询算法（绝大多数情况下都足够了），也可以使用官方提供的第二种随机算法或者自定义算法。\n4.1 随机算法\n顾名思义，完全随机地选择服务实例。\n按照官方文档复制粘贴即可</p>\n<p>结合rest进行远程调用\n</code></pre></p>\n<p>@Configuration\n@LoadBalancerClient(value = &quot;cloud-payment-service&quot;,\n//不填写value值则默认将负载均衡配置应用于所有服务调用\n//value值大小写一定要和想要修改的注册进服务中心的微服务名称必须一样\nconfiguration = RestTemplateConfig.class)\npublic class RestTemplateConfig {\n@Bean\n@LoadBalanced\npublic RestTemplate restTemplate() {\nreturn new RestTemplate();\n}</p>\n<p>@Bean\nReactorLoadBalancer&lt;ServiceInstance&gt; randomLoadBalancer(Environment environment,\nLoadBalancerClientFactory loadBalancerClientFactory) {\nString name = environment.getProperty(LoadBalancerClientFactory.PROPERTY_NAME);</p>\n<pre><code>return new RandomLoadBalancer(loadBalancerClientFactory.getLazyProvider(name, ServiceInstanceListSupplier.class), name);\n</code></pre>\n<p>}\n}\n</code></pre></p>\n<p>结合openFeign进行远程调用</p>\n<pre><code>\n<p>@Configuration\n@LoadBalancerClient(value = &quot;cloud-payment-service&quot;,\n//不填写value值则默认将负载均衡配置应用于所有服务调用\n//value值大小写一定要和想要修改的注册进服务中心的微服务名称必须一样\nconfiguration = FeignConfiguration.class)\npublic class FeignConfiguration {</p>\n@Bean\npublic ReactorServiceInstanceLoadBalancer loadBalancer(Environment environment,\n                                                       LoadBalancerClientFactory loadBalancerClientFactory) {\n    String name = environment.getProperty(LoadBalancerClientFactory.PROPERTY_NAME);\n    return new RandomLoadBalancer(loadBalancerClientFactory.getLazyProvider(name, ServiceInstanceListSupplier.class), name);\n}\n}\n</code></pre>\n<h2 id=\"42-自定义算法\">4.2 自定义算法</h2>\n<pre><code>实现该接口（具体我就不实现了）\n</code></pre>\n<p><code><pre>\npublic class MyLoadBalancer implements ReactorServiceInstanceLoadBalancer {\nprivate final String serviceId;\nprivate ObjectProvider<ServiceInstanceListSupplier> serviceInstanceListSupplierProvider;</p></p>\n<pre><code>public MyLoadBalancer(ObjectProvider&lt;ServiceInstanceListSupplier&gt; serviceInstanceListSupplierProvider, String serviceId) {\n    this.serviceId = serviceId;\n    this.serviceInstanceListSupplierProvider = serviceInstanceListSupplierProvider;\n}\n<p>@Override\npublic Mono&lt;Response&lt;ServiceInstance&gt;&gt; choose(Request request) {\nreturn null;\n}\n}\n</code></pre></p>\n<p>然后修改ReactorServiceInstanceLoadBalancer返回的实现对象即可</p>\n<p>return new MyLoadBalancer(loadBalancerClientFactory.getLazyProvider(name, ServiceInstanceListSupplier.class), name);\n<h1 id=\"5-总结\">5. 总结</h1>\n<p>LoadBalancer虽然底层思想大多非常简单，且不经常修改，但是了解其底层原理仍有助于对于负载均衡的使用。</p>\n', '2026-02-03 01:58:15', '2026-02-08 20:57:52');
INSERT INTO `article_content` VALUES (25, 26, '<p>在学习的过程中，我对类和接口之外的一个特殊存在----注解，产生好奇，由此探索学习了一下。在本文中，我会通过一个自定义注解（结合SpringAOP）的案例来讲解注解的相关知识。</p>\n<p>目录</p>\n<p>1.JAVA元注解</p>\n<pre><code>    1.1 @Target\n<pre><code>1.2 @Retention\n<p>1.3 @Documented</p>\n<p>1.4 @Inherited</p>\n<p>1.5 @Repeatable\n</code></pre></p>\n<p></code></pre></p>\n<ol start=\"2\">\n<li>\n<p>自定义注解（结合AOP）</p>\n<pre><code> 2.1 依赖\n<p>2.2 自定义注解</p>\n<p>2.3 定义AOP切面类</p>\n<p>2.3 测试\n</code></pre></p>\n</li>\n<li>\n<p>总结</p>\n</li>\n</ol>\n<p>1.JAVA元注解\nJava 元注解（Meta-Annotation）是用于注解其他注解的特殊注解。它们定义了自定义注解的行为和约束。Java 提供了五个常见的元注解</p>\n<pre><code>    1.1 @Target\n    @Target元注解是用于指定可以应用的目标元素\n<pre><code>它的value值为ElementType.class\n</code></pre>\n<p></code></pre></p>\n<p>public enum ElementType {\n//可以应用于类、接口（包括注解类型）或枚举声明\nTYPE,</p>\n<pre><code>//可以应用于字段（成员变量）\nFIELD,\n<p>//可以应用于方法声明\nMETHOD,</p>\n<p>//可以应用于方法参数\nPARAMETER,</p>\n<p>//可以应用于构造函数声明\nCONSTRUCTOR,</p>\n<p>//可以应用于局部变量声明\nLOCAL_VARIABLE,</p>\n<p>//可以应用于注解类型（用于嵌套注解）\nANNOTATION_TYPE,</p>\n<p>//可以应用于包声明\nPACKAGE,</p>\n<p>/**</p>\n<ul>\n<li>注解可以应用于类型参数声明（例如泛型类T）</li>\n<li></li>\n<li>@since 1.8\n*/\nTYPE_PARAMETER,</li>\n</ul>\n<p>/**</p>\n<ul>\n<li>注解可以应用于任何使用类型的地方</li>\n<li></li>\n<li>@since 1.8\n*/\nTYPE_USE,</li>\n</ul>\n<p>/**</p>\n<ul>\n<li>注解可以应用于模块声明</li>\n<li></li>\n<li>@since 9\n*/\nMODULE,</li>\n</ul>\n<p>/**</p>\n<ul>\n<li>注解可以应用于记录组件</li>\n<li></li>\n<li>@jls 8.10.3 Record Members</li>\n<li>@jls 9.7.4 Where Annotations May Appear</li>\n<li></li>\n<li>@since 16\n*/\nRECORD_COMPONENT;\n</code></pre></li>\n</ul>\n<p>}\nAI写代码\njava\n运行</p>\n<pre><code>    1.2 @Retention\n    @Retention元注解指定注解的保留策略，即注解在什么阶段可见。\n<pre><code>它的value值为RetentionPolicy.class类\n</code></pre>\n<p></code></pre></p>\n<p>public enum RetentionPolicy {</p>\n<pre><code>//注解只在源代码中可见，编译时会被丢弃\nSOURCE,\n<p>//注解在字节码文件中存在，但运行时不可见（默认）\nCLASS,</p>\n<p>//注解在运行时保留，可通过反射访问\nRUNTIME\n</code></pre></p>\n<p>}\nAI写代码\njava\n运行</p>\n<pre><code>    1.3 @Documented\n    @Documented注解用于指定该注解是否会被javadoc或类似工具提取，若被@Documented注解修饰，那么该注解的元素会被包含在生成的各种文档内。（文档内会显示该类或方法被@Documented修饰的注解所修饰）\n<pre><code>1.4 @Inherited\n@Inherited注解用于指定某个注解是否可以被子类继承。如果父类使用了某个带有@Inherited的注解，那么子类也会继承该注解。这个元注解只能用于类级别的注解。\n<p>例如，Parent具备@MyAnnotation(带有@Inherited)，那么当child类继承Parent类时，也会一并继承@MyAnnotation类。</p>\n<p>1.5 @Repeatable\n@Repeatable元注解允许同一个元素上多次使用同一类型的注解（jdk1.8引入）。为了使得注解可以重复，必须定义一个容器来持有多个相同类型的注解。\n</code></pre></p>\n<p></code></pre></p>\n<p>@Repeatable(MyAnnotations.class)  //传入容器的字节码\npublic @interface MyAnnotation {\nString value();\n}</p>\n<p>public @interface MyAnnotations {\nMyAnnotation[] value();\n}\nAI写代码\njava\n运行\n使用方式：</p>\n<p>@MyAnnotation(&quot;First&quot;)\n@MyAnnotation(&quot;Second&quot;)\npublic class MyClass {\n}\nAI写代码\njava\n运行\n2. 自定义注解（结合AOP）\n接下来我会通过一个自定义注解来计算方法耗时的例子来讲解注解的编写</p>\n<pre><code>    2.1 依赖\n&lt;dependencies&gt;\n    &lt;dependency&gt;\n        &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;\n        &lt;artifactId&gt;spring-boot-starter-web&lt;/artifactId&gt;\n    &lt;/dependency&gt;\n    &lt;!-- 引入aop支持 --&gt;\n    &lt;dependency&gt;\n        &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;\n        &lt;artifactId&gt;spring-boot-starter-aop&lt;/artifactId&gt;\n    &lt;/dependency&gt;\n    &lt;dependency&gt;\n        &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;\n        &lt;artifactId&gt;spring-boot-starter&lt;/artifactId&gt;\n    &lt;/dependency&gt;\n    &lt;dependency&gt;\n        &lt;groupId&gt;org.projectlombok&lt;/groupId&gt;\n        &lt;artifactId&gt;lombok&lt;/artifactId&gt;\n    &lt;/dependency&gt;\n<p>&lt;/dependencies&gt;\n</code></pre></p>\n<p>AI写代码</p>\n<pre><code>    2.2 自定义注解\n</code></pre>\n<p>@Retention(RetentionPolicy.RUNTIME)    //运行时保留\n@Target({ElementType.TYPE, ElementType.METHOD}) //针对方法和类\npublic @interface MyTarget {\n}\nAI写代码\njava\n运行\n2.3 定义AOP切面类\n@Component\n@Slf4j\n@Aspect\npublic class MyAnnotationAspect {</p>\n<pre><code>//切入点:注解标注在方法上\n@Pointcut(&quot;@annotation(com.atguigu.test.target.MyTarget)&quot;)\npublic void annotatedMethod() {}\n<p>//切入点:注解标注在类上\n@Pointcut(&quot;@within(com.atguigu.test.target.MyTarget)&quot;)\npublic void annotatedClass() {}</p>\n<p>// 使用 @Around 记录方法耗时，适用于方法和类上的注解\n@Around(&quot;annotatedMethod() || annotatedClass()&quot;)\npublic Object around(ProceedingJoinPoint joinPoint) throws Throwable {\nlong begin = System.currentTimeMillis();\nlog.info(&quot;进入方法&quot;);\n// 执行目标方法\nObject result = null;\ntry {\nresult = joinPoint.proceed();\n} catch (Throwable throwable) {\nlog.error(&quot;方法执行异常&quot;+throwable.getMessage());\nthrow throwable; // 将异常继续抛出\n}</p>\n<pre><code>long duration = System.currentTimeMillis() - begin;\nlog.info(&amp;quot;离开方法&amp;quot;);\nlog.info(&amp;quot;访问方法时长: &amp;quot; + duration + &amp;quot; 毫秒&amp;quot;);\nreturn result; // 返回目标方法的执行结果\n</code></pre>\n<p>}\n</code></pre></p>\n<p>}\nAI写代码\njava\n运行</p>\n<pre><code>    2.3 测试\n</code></pre>\n<p>@RestController\npublic class MyController {</p>\n<pre><code>@MyTarget\n@GetMapping(&quot;/myAnnotation/test&quot;)\npublic String test() {\n    return &quot;test&quot;;\n}\n</code></pre>\n<p>}\nAI写代码\njava\n运行\n启动服务后，访问localhost:8080/myAnnotation/test</p>\n<pre><code>    出现以下情况代表测试成功        再把@MyTarget注解移动到类上\n<pre><code>重启服务后再次访问localhost:8080/myAnnotation/test\n</code></pre>\n<p></code></pre></p>\n<ol start=\"3\">\n<li>总结\nJava 元注解为自定义注解的行为提供了规则和约束，确保注解可以正确地应用、保留和处理。在实际开发中，理解元注解的用途可以帮助开发者创建功能强大的自定义注解。</li>\n</ol>\n', '2026-02-03 01:58:46', '2026-02-08 20:13:39');
INSERT INTO `article_content` VALUES (26, 27, '<pre><code>  ThreadLocal是多线程情况下常用的一种线程隔离的变量，今天我们就来了解一下它的底层是如何实现的\n</code></pre>\n<p>目录</p>\n<p>一. 简介</p>\n<p>二. 基本使用方式</p>\n<p>三. 原理解析</p>\n<pre><code>    3.1 ThreadLocalMap\n<pre><code>3.2 get()方法\n<p>3.3 set()方法</p>\n<p>3.4 架构图\n</code></pre></p>\n<p></code></pre></p>\n<p>一. 简介\nThreadLocal，也称线程变量，每个ThreadLocal对象存储的变量仅仅属于当前线程，对于其他线程而言，无法获取到该变量,是一种线程隔离的变量，适用于一些在每个线程的上下文中，需要频繁地获取该变量，但处于需求或隐私考虑，需要独属于该线程的情况。</p>\n<pre><code>    作用：\n</code></pre>\n<p>提供线程独立性：每个线程可以拥有自己的变量副本，不会受到其他线程的影响，确保数据独立和安全。</p>\n<p>避免线程同步：通过 ThreadLocal，可以避免使用锁机制来处理线程间的数据共享问题，从而简化并发编程，提升程序的性能。</p>\n<p>简化线程上下文传递：在多线程环境中，ThreadLocal 可以隐式地存储线程特有的数据，避免在方法调用中显式传递这些数据，尤其在复杂的调用链中非常实用。</p>\n<p>维护线程状态：ThreadLocal 可以用于保存与线程生命周期相关的状态信息，例如当前线程处理的事务、数据库连接、用户信息等</p>\n<p>二. 基本使用方式\nThreadLocal支持传入泛型</p>\n<p>public class Main {\nstatic ThreadLocal threadLocal = new ThreadLocal();\nstatic ThreadLocal<String> threadLocal2 = new ThreadLocal();\npublic static void main(String[] args) {\nthreadLocal.set(1);\nSystem.out.println(threadLocal.get());\nthreadLocal2.set(&quot;B&quot;);\nSystem.out.println(threadLocal2.get());\n//演示线程隔离\nnew Thread(()-&gt;{\nSystem.out.println(threadLocal.get());\n}).start();\n}\n}\nAI写代码\njava\n运行</p>\n<pre><code>    运行结果：\n</code></pre>\n<p>三. 原理解析\n3.1 ThreadLocalMap\nThreadLocal的线程独立性底层是基于ThreadLocal的一个静态内部类ThreadLocalMap实现的，首先让我们粗略了解一下ThreadLocalMap：</p>\n<p>static class ThreadLocalMap {</p>\n<pre><code>    /**\n     * The entries in this hash map extend WeakReference, using\n     * its main ref field as the key (which is always a\n     * ThreadLocal object).  Note that null keys (i.e. entry.get()\n     * == null) mean that the key is no longer referenced, so the\n     * entry can be expunged from table.  Such entries are referred to\n     * as &quot;stale entries&quot; in the code that follows.\n     */\n    static class Entry extends WeakReference&lt;ThreadLocal&lt;?&gt;&gt; {\n        /** The value associated with this ThreadLocal. */\n        Object value;\n<pre><code>    Entry(ThreadLocal&amp;lt;?&amp;gt; k, Object v) {\n        super(k);\n        value = v;\n    }\n}\n<p>/**</p>\n<ul>\n<li>The table, resized as necessary.</li>\n<li>table.length MUST always be a power of two.\n*/\nprivate Entry[] table;</li>\n</ul>\n<p>/**</p>\n<ul>\n<li>.......\n*/\n</code></pre></li>\n</ul>\n<p></code></pre></p>\n<p>}<br />\nAI写代码\njava\n运行</p>\n<pre><code>    可以看到的是ThreadLocalMap的每个节点的key值，即ThreadLocal对象是弱引用，也就是说会在每次gc的时候进行回收，这可能是设计者想要避免OOM问题所使用的特殊设计。\n<pre><code>但是大家有没有发现一个问题;value值仍然是强引用，gc的时候不会回收\n<p>也就是说，如果在程序运行情况下，程序内存中会累积一个又一个线程的ThreadLocalMap的value值的垃圾信息，那么总有一天也会出现OOM问题！</p>\n<p>所以虽然设计者考虑到了使用ThreadLocal时尽量避免OOM问题，但没有完全解决，仍然需要我们每次在使用完成后，调用threadLocal.remove()方法：\n</code></pre></p>\n<p>public void remove() {\nThreadLocalMap m = getMap(Thread.currentThread());\nif (m != null)\nm.remove(this);\n}\nstatic class ThreadLocalMap {\n//...</p>\n<pre><code>private void remove(ThreadLocal&amp;lt;?&amp;gt; key) {\n    Entry[] tab = table;\n    int len = tab.length;\n    int i = key.threadLocalHashCode &amp;amp; (len-1);\n    for (Entry e = tab[i];\n         e != null;\n         e = tab[i = nextIndex(i, len)]) {\n        if (e.get() == key) {\n            e.clear();\n            expungeStaleEntry(i);\n            return;\n        }\n    }\n}\n<p>//...\n</code></pre></p>\n<p>}\n</code></pre></p>\n<p>AI写代码\njava\n运行</p>\n<pre><code>    remove()方法会将ThreadLocalMap所有节点设置为null，这样就能在gc的时候被回收了。\n<pre><code>另外我们可以看到ThreadLocalMap中有一个Entry数组，但是与HashMap相似相非\n</code></pre>\n<p>private void set(ThreadLocal&lt;?&gt; key, Object value) {</p>\n<pre><code>    // We don\'t use a fast path as with get() because it is at\n    // least as common to use set() to create new entries as\n    // it is to replace existing ones, in which case, a fast\n    // path would fail more often than not.\n<pre><code>Entry[] tab = table;\nint len = tab.length;\nint i = key.threadLocalHashCode &amp;amp;amp; (len-1);\n<p>for (Entry e = tab[i];\ne != null;\ne = tab[i = nextIndex(i, len)]) {\nThreadLocal&amp;amp;lt;?&amp;amp;gt; k = e.get();</p>\n<pre><code>if (k == key) {\n    e.value = value;\n    return;\n}\n<p>if (k == null) {\nreplaceStaleEntry(key, value, i);\nreturn;\n}\n</code></pre></p>\n<p>}</p>\n<p>tab[i] = new Entry(key, value);\nint sz = ++size;\n//重新散列与删除key值为null的结点\nif (!cleanSomeSlots(i, sz) &amp;amp;amp;&amp;amp;amp; sz &amp;amp;gt;= threshold)\nrehash();\n</code></pre></p>\n<p></code></pre></p>\n<p>}\nprivate static int nextIndex(int i, int len) {\nreturn ((i + 1 &lt; len) ? i + 1 : 0);\n}\n</code></pre></p>\n<p>AI写代码\njava\n运行</p>\n<pre><code>     相同点：ThreadLocalMap和HashMap一样，会先对value值进行哈希，计算出value值将要落在数组内的坐标。\n<pre><code>不同点：HashMap采用拉链法/红黑树解决哈希冲突，而ThreadLocalMap采用向后寻找空余位的方式解决哈希冲突。\n<p>总结一下，ThreadLocalMap是一个ThreadLocalMap的静态内部类，可以看作一个key值限定为ThreadLocal，做了些特殊处理的哈希表。</p>\n<p>3.2 get()方法\n</code></pre></p>\n<p>public T get() {\nThread t = Thread.currentThread();\nThreadLocalMap map = getMap(t);\nif (map != null) {\nThreadLocalMap.Entry e = map.getEntry(this);\nif (e != null) {\n@SuppressWarnings(&quot;unchecked&quot;)\nT result = (T)e.value;\nreturn result;\n}\n}\n//初始化ThreadLocalMap\nreturn setInitialValue();\n}\nstatic class ThreadLocalMap {\n//......</p>\n<pre><code>ThreadLocalMap getMap(Thread t) {\n    return t.threadLocals;\n}\n<p>//......\n</code></pre></p>\n<p>}\n</code></pre></p>\n<p>AI写代码\njava\n运行</p>\n<pre><code>     可以看到ThreadLocal的get()方法，首先从当前线程Thread获取一个ThreadLocalMap对象引用，然后在该ThreadLocalMap哈希表中搜寻key值对应的value值返回。        \n</code></pre>\n<p>public class Thread implements Runnable {\n//...\nThreadLocal.ThreadLocalMap threadLocals = null;\n//...\n}\nAI写代码\njava\n运行\nthreadLocals是Thread中的一个非静态属性，也就是说它是每个Thread独有的一个引用，每次初始化threadLocals会在堆区开辟一个新的ThreadLocalMap对象</p>\n<pre><code>    3.3 set()方法\npublic void set(T value) {\n    Thread t = Thread.currentThread();\n    ThreadLocalMap map = getMap(t);\n    if (map != null) {\n        map.set(this, value);\n    } else {\n        createMap(t, value);\n    }\n}\nstatic class ThreadLocalMap {\n    //......\n    private void set(ThreadLocal&lt;?&gt; key, Object value) {\n<pre><code>    // We don\'t use a fast path as with get() because it is at\n    // least as common to use set() to create new entries as\n    // it is to replace existing ones, in which case, a fast\n    // path would fail more often than not.\n<pre><code>Entry[] tab = table;\nint len = tab.length;\nint i = key.threadLocalHashCode &amp;amp;amp; (len-1);\n<p>for (Entry e = tab[i];\ne != null;\ne = tab[i = nextIndex(i, len)]) {\nif (e.refersTo(key)) {\ne.value = value;\nreturn;\n}</p>\n<pre><code>if (e.refersTo(null)) {\n    replaceStaleEntry(key, value, i);\n    return;\n}\n</code></pre>\n<p>}</p>\n<p>tab[i] = new Entry(key, value);\nint sz = ++size;\n//重新散列与删除key值为null的结点\nif (!cleanSomeSlots(i, sz) &amp;amp;amp;&amp;amp;amp; sz &amp;amp;gt;= threshold)\nrehash();\n</code></pre></p>\n<p>}</p>\n<p>//......\n</code></pre></p>\n<p>}\n</code></pre></p>\n<p>AI写代码\njava\n运行</p>\n<pre><code>     与get()方法一致，threadLocal会通过调用Thread.currentThread()获取当前Thread对象，再通过getMap(t)获取当前线程指向的ThreadLocalMap，并尝试像哈希表一样插入key和value\n<pre><code> 3.4 架构图\n厘清一下以上分析的脉络，我们可以得到下图：\n<p>threadLocal:堆区开辟的ThreadLocal对象的一个引用</p>\n<p>ThreadLocal:堆区开辟的对象</p>\n<p>Thread.currentThread():native修饰的本地方法，返回当前线程Thread对象</p>\n<p>Thread对象：threadLocals属性默认为null，第一次使用threadLocal.set()方法后在堆区新开辟一个ThreadLocalMap对象</p>\n<p>ThreadLocalMap:使用ThreadLocal作为key值，传入值作为value值</p>\n<p>也就是说在多线程情况下如下图所示：</p>\n<p>尽管threadLocal引用的是堆区中的同一个ThreadLocal对象，但是由于ThreadLocalMap不同，那么存储与取出的value值互不影响，实现线程独立性。</p>\n<p>本篇文章到此结束，希望能对大家有所帮助\n</code></pre></p>\n<p></code></pre></p>\n', '2026-02-03 01:59:15', '2026-02-08 20:13:38');
INSERT INTO `article_content` VALUES (27, 28, '<ol>\n<li>\n<p>理论分析\nzookeeper 和Linux一样，采用目录树的方式管理结点，目录层级间以 / 区分</p>\n<pre><code> 每个数据节点在 ZooKeeper 中被称为 znode，它是 ZooKeeper 中数据的最小单元。由于ZooKeeper 主要用于协调服务，出于性能和一致性考虑，每个节点的存放数据上限为1M\n<p>1.1 结点类型\nznode有四种类型：</p>\n<p>1.持久化结点  (PERSISTENT）: 创建节点后一直存在</p>\n<ol start=\"2\">\n<li>\n<p>持久化有序结点（PERSISTENT_SEQUENTIAL）：在持久化结点的基础上，zookeeper会自动根据创建顺序，在结点名称后面加上一串序号</p>\n</li>\n<li>\n<p>临时结点（EPHEMERAL）：在zookeeper与客户端失去连接后自动删除</p>\n</li>\n<li>\n<p>临时有序结点（EPHEMERAL_SEQUENTIAL）：在临时结点的基础上，zookeeper会自动根据创建顺序，在结点名称后面加上一串序号</p>\n</li>\n</ol>\n<p>1.2 监听器\nWatcher 监听机制是 Zookeeper 中非常重要的特性。结点可以绑定监听事件，当监听事件发生的时候,Zookeeper会向客户端发送通知事件，执行监听器的回调方法。</p>\n<p>1.3 实现原理\n我们首先新建一个&quot;/locks&quot;的持久化结点,用来管理表示锁的子节点。（实际场景使用可以根据不同锁对象划分成更细致的持久化结点,比如&quot;/locks/bilibili/comment/publish&quot;）</p>\n<p>当用户尝试获取锁的时候，在&quot;locks&quot;结点下新建一个临时有序结点,例如&quot;seq-00001&quot;</p>\n<p>新建结点成功后，系统进行检查，建立的结点是否是当前所有子节点中序号最小的一个</p>\n<p>如果是最小的一个，说明用户是当前锁的持有者，往下执行业务逻辑，执行完成后摧毁临时结点</p>\n<p>​​​​​​​</p>\n<p>如果不是最小的一个，为了避免不断地自旋检查空耗性能，一般采用注册监听器的方式减少性能消耗：监听前一个结点的摧毁事件。如果用户持有的结点前面还有其他结点，说明用户不是持有的人，不能执行业务逻辑，应当阻塞等待；直到用户前一个结点被摧毁，说明轮到用户持有锁了，可以继续往下执行业务逻辑。\n</code></pre></p>\n</li>\n<li>\n<p>手写实现简易zookeeper分布式锁\n1.1 依赖\n<dependency>\n<groupId>junit</groupId>\n<artifactId>junit</artifactId>\n<version>RELEASE</version>\n<scope>test</scope>\n</dependency></p>\n<pre><code> &lt;!--日志--&gt;\n &lt;dependency&gt;\n     &lt;groupId&gt;org.apache.logging.log4j&lt;/groupId&gt;\n     &lt;artifactId&gt;log4j-core&lt;/artifactId&gt;\n     &lt;version&gt;2.8.2&lt;/version&gt;\n &lt;/dependency&gt;\n<p>&lt;!--zookeeper--&gt;\n&lt;dependency&gt;\n&lt;groupId&gt;org.apache.zookeeper&lt;/groupId&gt;\n&lt;artifactId&gt;zookeeper&lt;/artifactId&gt;\n&lt;version&gt;3.5.6&lt;/version&gt;\n&lt;/dependency&gt;\n&lt;dependency&gt;\n&lt;groupId&gt;org.junit.jupiter&lt;/groupId&gt;\n&lt;artifactId&gt;junit-jupiter&lt;/artifactId&gt;\n&lt;version&gt;RELEASE&lt;/version&gt;\n&lt;scope&gt;compile&lt;/scope&gt;\n&lt;/dependency&gt;\n</code></pre></p>\n</li>\n</ol>\n<p>AI写代码</p>\n<pre><code>     1.2 常量定义\n</code></pre>\n<p>public interface ZkConstants {\n//连接地址\nString connectString = &quot;127.0.0.1:2181&quot;;\n// 连接超时时间\nint sessionTimeout = 2000;\n}\nAI写代码\njava\n运行\n1.3 实现zookeeper分布式锁\npublic class DistributedLock {</p>\n<pre><code>// zk客户端连接\nprivate ZooKeeper zkClient;\n<p>// 连接成功等待\nprivate CountDownLatch connectLatch = new CountDownLatch(1);\n// 前一个结点（锁）\nprivate String waitPath;\n// 结点删除等待\nprivate CountDownLatch waitLatch = new CountDownLatch(1);\n// 当前创建的结点（锁）\nprivate String createNode;</p>\n<p>/**</p>\n<ul>\n<li>\n<p>构造方法:初始化客户端连接</p>\n</li>\n<li></li>\n<li>\n<p>@throws IOException</p>\n</li>\n<li>\n<p>@throws InterruptedException</p>\n</li>\n<li>\n<p>@throws KeeperException\n*/\npublic DistributedLock() throws IOException, InterruptedException, KeeperException {\n//获取连接\nzkClient = new ZooKeeper(ZkConstants.connectString, ZkConstants.sessionTimeout, new Watcher() {\n@Override\npublic void process(WatchedEvent watchedEvent) {\n//连接成功，释放countDownLatch\nif (watchedEvent.getState() == Event.KeeperState.SyncConnected) {\nconnectLatch.countDown();\n}</p>\n<pre><code>     //前一个结点删除\n     if (watchedEvent.getType() == Event.EventType.NodeDeleted &amp;amp;&amp;amp; watchedEvent.getPath().equals(waitPath)) {\n         //解锁下一个结点\n         waitLatch.countDown();\n     }\n }\n</code></pre>\n<p>});\n//等待zk正常连接后，再往下执行\nconnectLatch.await();\n//判断根节点/locks是否存在\nStat exists = zkClient.exists(&quot;/locks&quot;, false);\nif (exists == null) {\n//创建根节点 -- 持久结点\nzkClient.create(&quot;/locks&quot;, &quot;locks&quot;.getBytes(), ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);\n}\n}</p>\n</li>\n</ul>\n<p>/**</p>\n<ul>\n<li>\n<p>加锁</p>\n</li>\n<li></li>\n<li>\n<p>@throws InterruptedException</p>\n</li>\n<li>\n<p>@throws KeeperException\n*/\npublic void zkLock() throws InterruptedException, KeeperException {\n//创建对应的临时带序号结点\ncreateNode = zkClient.create(&quot;/locks/&quot; + &quot;seq-&quot;, null, ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.EPHEMERAL_SEQUENTIAL);\n//判断创建节点是否是序号最小的结点\nList&lt;String&gt; children = zkClient.getChildren(&quot;/locks&quot;, false);\nif (children.size() == 1) {\nreturn;\n} else {\n//排序结点以得到当前创建结点的序号（等待锁的序位）\nCollections.sort(children);\n//获取生成的临时结点序号\nString thisNode = createNode.substring(&quot;/locks/&quot;.length());\n//获得排序\nint index = children.indexOf(thisNode);</p>\n<pre><code> if (index == -1) {\n     System.out.println(&amp;quot;数据异常&amp;quot;);\n } else if (index == 0) {\n     //最小序号结点，直接获取锁\n     return;\n } else {\n     //监听序号前一个结点\n     waitPath = &amp;quot;/locks/&amp;quot; + children.get(index - 1);\n     //true代表使用创建zkClient时初始化的监听器\n     zkClient.getData(waitPath, true, null);\n     waitLatch.await();\n }\n</code></pre>\n<p>}</p>\n</li>\n</ul>\n<p>}</p>\n<p>/**</p>\n<ul>\n<li>解锁</li>\n<li></li>\n<li>@throws InterruptedException</li>\n<li>@throws KeeperException\n*/\npublic void zkUnLock() throws InterruptedException, KeeperException {\n//删除临时带序号结点\nzkClient.delete(createNode, -1);\n}\n</code></pre></li>\n</ul>\n<p>}\nAI写代码\njava\n运行</p>\n<pre><code>    1.4 使用方式\n</code></pre>\n<p>public class DistributedLockTest {</p>\n<pre><code>public static void main(String[] args) throws IOException, InterruptedException, KeeperException {\n<pre><code>ExecutorService executorService = Executors.newFixedThreadPool(2);\n<p>DistributedLock lock1 = new DistributedLock();\nDistributedLock lock2 = new DistributedLock();\n//多线程获取锁1\nCompletableFuture.supplyAsync(() -&amp;gt; {\ntry {\nlock1.zkLock();\nSystem.out.println(&amp;quot;线程&amp;quot; + Thread.currentThread().getName() + &amp;quot;获取到锁......&amp;quot;);\nThread.sleep(5000);\nlock1.zkUnLock();\nSystem.out.println(&amp;quot;线程&amp;quot; + Thread.currentThread().getName() + &amp;quot;释放锁......&amp;quot;);\n} catch (InterruptedException e) {\nthrow new RuntimeException(e);\n} catch (KeeperException e) {\nthrow new RuntimeException(e);\n}\nreturn true;\n}, executorService);\n//多线程获取锁2\nCompletableFuture.supplyAsync(() -&amp;gt; {\ntry {\nlock2.zkLock();\nSystem.out.println(&amp;quot;线程&amp;quot; + Thread.currentThread().getName() + &amp;quot;获取到锁......&amp;quot;);\nThread.sleep(5000);\nlock2.zkUnLock();\nSystem.out.println(&amp;quot;线程&amp;quot; + Thread.currentThread().getName() + &amp;quot;释放锁......&amp;quot;);\n} catch (InterruptedException e) {\nthrow new RuntimeException(e);\n} catch (KeeperException e) {\nthrow new RuntimeException(e);\n}\nreturn true;\n}, executorService);</p>\n<p>executorService.shutdown();\n</code></pre></p>\n<p>}\n</code></pre></p>\n<p>}\nAI写代码\njava\n运行</p>\n<ol start=\"3\">\n<li>\n<p>引入Curator框架实现zookeeper分布式锁\n实际生产环境下，自然不可能手写这么多代码处理分布式锁，且不提很多地方的代码可复用，CountDownLatch反复处理带来的代码复杂性高，并且一些可重入锁、异常处理等逻辑上文也并没有完善。</p>\n<pre><code> 生产场景中被广泛使用的zookeeper分布式锁的框架便是Curator\n<p>2.1 框架依赖\n/..\n省略\n../\n&lt;!--Curator--&gt;\n&lt;dependency&gt;\n&lt;groupId&gt;org.apache.curator&lt;/groupId&gt;\n&lt;artifactId&gt;curator-framework&lt;/artifactId&gt;\n&lt;version&gt;4.3.0&lt;/version&gt;\n&lt;/dependency&gt;\n&lt;dependency&gt;\n&lt;groupId&gt;org.apache.curator&lt;/groupId&gt;\n&lt;artifactId&gt;curator-recipes&lt;/artifactId&gt;\n&lt;version&gt;4.3.0&lt;/version&gt;\n&lt;/dependency&gt;\n&lt;dependency&gt;\n&lt;groupId&gt;org.apache.curator&lt;/groupId&gt;\n&lt;artifactId&gt;curator-client&lt;/artifactId&gt;\n&lt;version&gt;4.3.0&lt;/version&gt;\n&lt;/dependency&gt;\n</code></pre></p>\n</li>\n</ol>\n<p>AI写代码</p>\n<pre><code>    2.2 使用方式\n</code></pre>\n<p>public class CuratorLockTest {</p>\n<pre><code>public static void main(String[] args) {\n    //创建分布式锁1\n    InterProcessLock lock1 = new InterProcessMutex(getCuratorFramework(), &quot;/locks&quot;);\n    InterProcessLock lock2 = new InterProcessMutex(getCuratorFramework(), &quot;/locks&quot;);\n<pre><code>ExecutorService executorService = Executors.newFixedThreadPool(2);\n<p>executorService.execute(() -&amp;gt; {\ntry {\nlock1.acquire();\nSystem.out.println(&amp;quot;线程1获取到锁&amp;quot;);</p>\n<pre><code>    //curator支持可重入锁\n    lock1.acquire();\n    System.out.println(&amp;amp;quot;线程1 再次获取到锁&amp;amp;quot;);\n<pre><code>Thread.sleep(5000);\n<p>lock1.release();\nSystem.out.println(&amp;amp;amp;quot;线程1 释放锁&amp;amp;amp;quot;);</p>\n<p>lock1.release();\nSystem.out.println(&amp;amp;amp;quot;线程1 再次释放锁&amp;amp;amp;quot;);\n</code></pre></p>\n<p>} catch (Exception e) {\nthrow new RuntimeException(e);\n}\n</code></pre></p>\n<p>});</p>\n<p>executorService.execute(() -&amp;gt; {\ntry {\nlock2.acquire();\nSystem.out.println(&amp;quot;线程2获取到锁&amp;quot;);</p>\n<pre><code>        lock2.acquire();\n        System.out.println(&amp;amp;quot;线程2 再次获取到锁&amp;amp;quot;);\n<pre><code>    Thread.sleep(5000);\n<pre><code>lock2.release();\nSystem.out.println(&amp;amp;amp;amp;quot;线程2 释放锁&amp;amp;amp;amp;quot;);\n<p>lock2.release();\nSystem.out.println(&amp;amp;amp;amp;quot;线程2 再次释放锁&amp;amp;amp;amp;quot;);\n</code></pre></p>\n<p>} catch (Exception e) {\nthrow new RuntimeException(e);\n}\n</code></pre></p>\n<p>}\n</code></pre></p>\n<p>);\nexecutorService.shutdown();\n</code></pre></p>\n<p>}</p>\n<p>public static CuratorFramework getCuratorFramework() {\n//4秒超时，重试3次\nExponentialBackoffRetry exponentialBackoffRetry = new ExponentialBackoffRetry(4000, 3);</p>\n<pre><code>CuratorFramework client = CuratorFrameworkFactory.builder().connectString(ZkConstants.connectString)\n        .connectionTimeoutMs(ZkConstants.sessionTimeout)\n        .sessionTimeoutMs(ZkConstants.sessionTimeout)\n        .retryPolicy(exponentialBackoffRetry)\n        .build();\nclient.start();\nSystem.out.println(&amp;quot;zookeeper 启动成功...&amp;quot;);\nreturn client;\n</code></pre>\n<p>}\n</code></pre></p>\n<p>}\nAI写代码\njava\n运行</p>\n<pre><code>    希望能对大家理解zookeeper分布式锁有所帮助\n</code></pre>\n', '2026-02-03 02:00:33', '2026-02-08 20:22:12');
INSERT INTO `article_content` VALUES (28, 29, '<p>一、写在前面</p>\n<p>1.1 线程池是什么</p>\n<p>线程池（Thread Pool）是一种基于池化思想管理线程的工具，经常出现在多线程服务器中，如MySQL。</p>\n<p>线程过多会带来额外的开销，其中包括创建销毁线程的开销、调度线程的开销等等，同时也降低了计算机的整体性能。线程池维护多个线程，等待监督管理者分配可并发执行的任务。这种做法，一方面避免了处理任务时创建销毁线程开销的代价，另一方面避免了线程数量膨胀导致的过分调度问题，保证了对内核的充分利用。</p>\n<p>而本文描述线程池是JDK中提供的ThreadPoolExecutor类。</p>\n<p>当然，使用线程池可以带来一系列好处：</p>\n<p>降低资源消耗：通过池化技术重复利用已创建的线程，降低线程创建和销毁造成的损耗。</p>\n<p>提高响应速度：任务到达时，无需等待线程创建即可立即执行。</p>\n<p>提高线程的可管理性：线程是稀缺资源，如果无限制创建，不仅会消耗系统资源，还会因为线程的不合理分布导致资源调度失衡，降低系统的稳定性。使用线程池可以进行统一的分配、调优和监控。</p>\n<p>提供更多更强大的功能：线程池具备可拓展性，允许开发人员向其中增加更多的功能。比如延时定时线程池ScheduledThreadPoolExecutor，就允许任务延期执行或定期执行。</p>\n<p>1.2 线程池解决的问题是什么</p>\n<p>线程池解决的核心问题就是资源管理问题。在并发环境下，系统不能够确定在任意时刻中，有多少任务需要执行，有多少资源需要投入。这种不确定性将带来以下若干问题：</p>\n<p>频繁申请/销毁资源和调度资源，将带来额外的消耗，可能会非常巨大。</p>\n<p>对资源无限申请缺少抑制手段，易引发系统资源耗尽的风险。</p>\n<p>系统无法合理管理内部的资源分布，会降低系统的稳定性。</p>\n<p>为解决资源分配这个问题，线程池采用了“池化”（Pooling）思想。池化，顾名思义，是为了最大化收益并最小化风险，而将资源统一在一起管理的一种思想。</p>\n<p>Pooling is the grouping together of resources (assets, equipment, personnel, effort, etc.) for the purposes of maximizing advantage or minimizing risk to the users. The term is used in finance, computing and equipment management.——wikipedia\n“池化”思想不仅仅能应用在计算机领域，在金融、设备、人员管理、工作管理等领域也有相关的应用。</p>\n<p>在计算机领域中的表现为：统一管理IT资源，包括服务器、存储、和网络资源等等。通过共享资源，使用户在低投入中获益。除去线程池，还有其他比较典型的几种使用策略包括：</p>\n<p>内存池(Memory Pooling)：预先申请内存，提升申请内存速度，减少内存碎片。</p>\n<p>连接池(Connection Pooling)：预先申请数据库连接，提升申请连接的速度，降低系统的开销。</p>\n<p>实例池(Object Pooling)：循环使用对象，减少资源在初始化和释放时的昂贵损耗。</p>\n<p>在了解完“是什么”和“为什么”之后，下面我们来一起深入一下线程池的内部实现原理。</p>\n<p>二、线程池核心设计与实现</p>\n<p>在前文中，我们了解到：线程池是一种通过“池化”思想，帮助我们管理线程而获取并发性的工具，在Java中的体现是ThreadPoolExecutor类。那么它的的详细设计与实现是什么样的呢？我们会在本章进行详细介绍。</p>\n<p>2.1 总体设计</p>\n<p>Java中的线程池核心实现类是ThreadPoolExecutor，本章基于JDK 1.8的源码来分析Java线程池的核心设计与实现。我们首先来看一下ThreadPoolExecutor的UML类图，了解下ThreadPoolExecutor的继承关系。</p>\n<p>图片\n图1 ThreadPoolExecutor UML类图\nThreadPoolExecutor实现的顶层接口是Executor，顶层接口Executor提供了一种思想：将任务提交和任务执行进行解耦。用户无需关注如何创建线程，如何调度线程来执行任务，用户只需提供Runnable对象，将任务的运行逻辑提交到执行器(Executor)中，由Executor框架完成线程的调配和任务的执行部分。ExecutorService接口增加了一些能力：（1）扩充执行任务的能力，补充可以为一个或一批异步任务生成Future的方法；（2）提供了管控线程池的方法，比如停止线程池的运行。</p>\n<p>AbstractExecutorService则是上层的抽象类，将执行任务的流程串联了起来，保证下层的实现只需关注一个执行任务的方法即可。最下层的实现类ThreadPoolExecutor实现最复杂的运行部分，ThreadPoolExecutor将会一方面维护自身的生命周期，另一方面同时管理线程和任务，使两者良好的结合从而执行并行任务。</p>\n<p>ThreadPoolExecutor是如何运行，如何同时维护线程和执行任务的呢？其运行机制如下图所示：</p>\n<p>图片\n图2 ThreadPoolExecutor运行流程\n线程池在内部实际上构建了一个生产者消费者模型，将线程和任务两者解耦，并不直接关联，从而良好的缓冲任务，复用线程。线程池的运行主要分成两部分：任务管理、线程管理。任务管理部分充当生产者的角色，当任务提交后，线程池会判断该任务后续的流转：（1）直接申请线程执行该任务；（2）缓冲到队列中等待线程执行；（3）拒绝该任务。线程管理部分是消费者，它们被统一维护在线程池内，根据任务请求进行线程的分配，当线程执行完任务后则会继续获取新的任务去执行，最终当线程获取不到任务的时候，线程就会被回收。</p>\n<p>接下来，我们会按照以下三个部分去详细讲解线程池运行机制：</p>\n<p>线程池如何维护自身状态。</p>\n<p>线程池如何管理任务。</p>\n<p>线程池如何管理线程。</p>\n<p>2.2 生命周期管理</p>\n<p>线程池运行的状态，并不是用户显式设置的，而是伴随着线程池的运行，由内部来维护。线程池内部使用一个变量维护两个值：运行状态(runState)和线程数量 (workerCount)。在具体实现中，线程池将运行状态(runState)、线程数量 (workerCount)两个关键参数的维护放在了一起，如下代码所示：</p>\n<p>private final AtomicInteger ctl = new AtomicInteger(ctlOf(RUNNING, 0));\nctl这个AtomicInteger类型，是对线程池的运行状态和线程池中有效线程的数量进行控制的一个字段， 它同时包含两部分的信息：线程池的运行状态 (runState) 和线程池内有效线程的数量 (workerCount)，高3位保存runState，低29位保存workerCount，两个变量之间互不干扰。用一个变量去存储两个值，可避免在做相关决策时，出现不一致的情况，不必为了维护两者的一致，而占用锁资源。通过阅读线程池源代码也可以发现，经常出现要同时判断线程池运行状态和线程数量的情况。线程池也提供了若干方法去供用户获得线程池当前的运行状态、线程个数。这里都使用的是位运算的方式，相比于基本运算，速度也会快很多。</p>\n<p>关于内部封装的获取生命周期状态、获取线程池线程数量的计算方法如以下代码所示：</p>\n<p>private static int runStateOf(int c)     { return c &amp; ~CAPACITY; } //计算当前运行状态\nprivate static int workerCountOf(int c)  { return c &amp; CAPACITY; }  //计算当前线程数量\nprivate static int ctlOf(int rs, int wc) { return rs | wc; }   //通过状态和线程数生成ctl\nThreadPoolExecutor的运行状态有5种，分别为：</p>\n<p>图片\n其生命周期转换如下入所示：</p>\n<p>图片\n图3 线程池生命周期\n2.3 任务执行机制</p>\n<p>2.3.1 任务调度</p>\n<p>任务调度是线程池的主要入口，当用户提交了一个任务，接下来这个任务将如何执行都是由这个阶段决定的。了解这部分就相当于了解了线程池的核心运行机制。</p>\n<p>首先，所有任务的调度都是由execute方法完成的，这部分完成的工作是：检查现在线程池的运行状态、运行线程数、运行策略，决定接下来执行的流程，是直接申请线程执行，或是缓冲到队列中执行，亦或是直接拒绝该任务。其执行过程如下：</p>\n<p>首先检测线程池运行状态，如果不是RUNNING，则直接拒绝，线程池要保证在RUNNING的状态下执行任务。</p>\n<p>如果workerCount &lt; corePoolSize，则创建并启动一个线程来执行新提交的任务。</p>\n<p>如果workerCount &gt;= corePoolSize，且线程池内的阻塞队列未满，则将任务添加到该阻塞队列中。</p>\n<p>如果workerCount &gt;= corePoolSize &amp;&amp; workerCount &lt; maximumPoolSize，且线程池内的阻塞队列已满，则创建并启动一个线程来执行新提交的任务。</p>\n<p>如果workerCount &gt;= maximumPoolSize，并且线程池内的阻塞队列已满, 则根据拒绝策略来处理该任务, 默认的处理方式是直接抛异常。</p>\n<p>其执行流程如下图所示：</p>\n<p>图片\n图4 任务调度流程\n2.3.2 任务缓冲</p>\n<p>任务缓冲模块是线程池能够管理任务的核心部分。线程池的本质是对任务和线程的管理，而做到这一点最关键的思想就是将任务和线程两者解耦，不让两者直接关联，才可以做后续的分配工作。线程池中是以生产者消费者模式，通过一个阻塞队列来实现的。阻塞队列缓存任务，工作线程从阻塞队列中获取任务。</p>\n<p>阻塞队列(BlockingQueue)是一个支持两个附加操作的队列。这两个附加的操作是：在队列为空时，获取元素的线程会等待队列变为非空。当队列满时，存储元素的线程会等待队列可用。阻塞队列常用于生产者和消费者的场景，生产者是往队列里添加元素的线程，消费者是从队列里拿元素的线程。阻塞队列就是生产者存放元素的容器，而消费者也只从容器里拿元素。</p>\n<p>下图中展示了线程1往阻塞队列中添加元素，而线程2从阻塞队列中移除元素：</p>\n<p>图片\n图5 阻塞队列\n使用不同的队列可以实现不一样的任务存取策略。在这里，我们可以再介绍下阻塞队列的成员：</p>\n<p>图片\n2.3.3 任务申请</p>\n<p>由上文的任务分配部分可知，任务的执行有两种可能：一种是任务直接由新创建的线程执行。另一种是线程从任务队列中获取任务然后执行，执行完任务的空闲线程会再次去从队列中申请任务再去执行。第一种情况仅出现在线程初始创建的时候，第二种是线程获取任务绝大多数的情况。</p>\n<p>线程需要从任务缓存模块中不断地取任务执行，帮助线程从阻塞队列中获取任务，实现线程管理模块和任务管理模块之间的通信。这部分策略由getTask方法实现，其执行流程如下图所示：</p>\n<p>图片\n图6 获取任务流程图\ngetTask这部分进行了多次判断，为的是控制线程的数量，使其符合线程池的状态。如果线程池现在不应该持有那么多线程，则会返回null值。工作线程Worker会不断接收新任务去执行，而当工作线程Worker接收不到任务的时候，就会开始被回收。</p>\n<p>2.3.4 任务拒绝</p>\n<p>任务拒绝模块是线程池的保护部分，线程池有一个最大的容量，当线程池的任务缓存队列已满，并且线程池中的线程数目达到maximumPoolSize时，就需要拒绝掉该任务，采取任务拒绝策略，保护线程池。</p>\n<p>拒绝策略是一个接口，其设计如下：</p>\n<p>public interface RejectedExecutionHandler {\nvoid rejectedExecution(Runnable r, ThreadPoolExecutor executor);\n}\n用户可以通过实现这个接口去定制拒绝策略，也可以选择JDK提供的四种已有拒绝策略，其特点如下：</p>\n<p>图片\n2.4 Worker线程管理</p>\n<p>2.4.1 Worker线程</p>\n<p>线程池为了掌握线程的状态并维护线程的生命周期，设计了线程池内的工作线程Worker。我们来看一下它的部分代码：</p>\n<p>private final class Worker extends AbstractQueuedSynchronizer implements Runnable{\nfinal Thread thread;//Worker持有的线程\nRunnable firstTask;//初始化的任务，可以为null\n}\nWorker这个工作线程，实现了Runnable接口，并持有一个线程thread，一个初始化的任务firstTask。thread是在调用构造方法时通过ThreadFactory来创建的线程，可以用来执行任务；firstTask用它来保存传入的第一个任务，这个任务可以有也可以为null。如果这个值是非空的，那么线程就会在启动初期立即执行这个任务，也就对应核心线程创建时的情况；如果这个值是null，那么就需要创建一个线程去执行任务列表（workQueue）中的任务，也就是非核心线程的创建。</p>\n<p>Worker执行任务的模型如下图所示：</p>\n<p>图片\n图7 Worker执行任务\n线程池需要管理线程的生命周期，需要在线程长时间不运行的时候进行回收。线程池使用一张Hash表去持有线程的引用，这样可以通过添加引用、移除引用这样的操作来控制线程的生命周期。这个时候重要的就是如何判断线程是否在运行。</p>\n<p>Worker是通过继承AQS，使用AQS来实现独占锁这个功能。没有使用可重入锁ReentrantLock，而是使用AQS，为的就是实现不可重入的特性去反应线程现在的执行状态。</p>\n<p>lock方法一旦获取了独占锁，表示当前线程正在执行任务中。</p>\n<p>如果正在执行任务，则不应该中断线程。</p>\n<p>如果该线程现在不是独占锁的状态，也就是空闲的状态，说明它没有在处理任务，这时可以对该线程进行中断。</p>\n<p>线程池在执行shutdown方法或tryTerminate方法时会调用interruptIdleWorkers方法来中断空闲的线程，interruptIdleWorkers方法会使用tryLock方法来判断线程池中的线程是否是空闲状态；如果线程是空闲状态则可以安全回收。</p>\n<p>在线程回收过程中就使用到了这种特性，回收过程如下图所示：</p>\n<p>图片\n图8 线程池回收过程\n2.4.2 Worker线程增加</p>\n<p>增加线程是通过线程池中的addWorker方法，该方法的功能就是增加一个线程，该方法不考虑线程池是在哪个阶段增加的该线程，这个分配线程的策略是在上个步骤完成的，该步骤仅仅完成增加线程，并使它运行，最后返回是否成功这个结果。addWorker方法有两个参数：firstTask、core。firstTask参数用于指定新增的线程执行的第一个任务，该参数可以为空；core参数为true表示在新增线程时会判断当前活动线程数是否少于corePoolSize，false表示新增线程前需要判断当前活动线程数是否少于maximumPoolSize，其执行流程如下图所示：</p>\n<p>图片\n图9 申请线程执行流程图\n2.4.3 Worker线程回收</p>\n<p>线程池中线程的销毁依赖JVM自动的回收，线程池做的工作是根据当前线程池的状态维护一定数量的线程引用，防止这部分线程被JVM回收，当线程池决定哪些线程需要回收时，只需要将其引用消除即可。Worker被创建出来后，就会不断地进行轮询，然后获取任务去执行，核心线程可以无限等待获取任务，非核心线程要限时获取任务。当Worker无法获取到任务，也就是获取的任务为空时，循环会结束，Worker会主动消除自身在线程池内的引用。</p>\n<p>try {\nwhile (task != null || (task = getTask()) != null) {\n//执行任务\n}\n} finally {\nprocessWorkerExit(w, completedAbruptly);//获取不到任务时，主动回收自己\n}\n线程回收的工作是在processWorkerExit方法完成的。</p>\n<p>图片\n图10 线程销毁流程\n事实上，在这个方法中，将线程引用移出线程池就已经结束了线程销毁的部分。但由于引起线程销毁的可能性有很多，线程池还要判断是什么引发了这次销毁，是否要改变线程池的现阶段状态，是否要根据新状态，重新分配线程。</p>\n<p>2.4.4 Worker线程执行任务</p>\n<p>在Worker类中的run方法调用了runWorker方法来执行任务，runWorker方法的执行过程如下：</p>\n<p>while循环不断地通过getTask()方法获取任务。</p>\n<p>getTask()方法从阻塞队列中取任务。</p>\n<p>如果线程池正在停止，那么要保证当前线程是中断状态，否则要保证当前线程不是中断状态。</p>\n<p>执行任务。</p>\n<p>如果getTask结果为null则跳出循环，执行processWorkerExit()方法，销毁线程。</p>\n<p>执行流程如下图所示：</p>\n<p>图片\n图11 执行任务流程</p>\n', '2026-02-03 02:10:22', '2026-02-03 02:14:38');
INSERT INTO `article_content` VALUES (29, 30, '<p>三、线程池在业务中的实践</p>\n<p>3.1 业务背景</p>\n<p>在当今的互联网业界，为了最大程度利用CPU的多核性能，并行运算的能力是不可或缺的。通过线程池管理线程获取并发性是一个非常基础的操作，让我们来看两个典型的使用线程池获取并发性的场景。</p>\n<p>场景1：快速响应用户请求</p>\n<p>描述：用户发起的实时请求，服务追求响应时间。比如说用户要查看一个商品的信息，那么我们需要将商品维度的一系列信息如商品的价格、优惠、库存、图片等等聚合起来，展示给用户。</p>\n<p>分析：从用户体验角度看，这个结果响应的越快越好，如果一个页面半天都刷不出，用户可能就放弃查看这个商品了。而面向用户的功能聚合通常非常复杂，伴随着调用与调用之间的级联、多级级联等情况，业务开发同学往往会选择使用线程池这种简单的方式，将调用封装成任务并行的执行，缩短总体响应时间。另外，使用线程池也是有考量的，这种场景最重要的就是获取最大的响应速度去满足用户，所以应该不设置队列去缓冲并发任务，调高corePoolSize和maxPoolSize去尽可能创造多的线程快速执行任务。</p>\n<p>图片\n图12 并行执行任务提升任务响应速度\n场景2：快速处理批量任务</p>\n<p>描述：离线的大量计算任务，需要快速执行。比如说，统计某个报表，需要计算出全国各个门店中有哪些商品有某种属性，用于后续营销策略的分析，那么我们需要查询全国所有门店中的所有商品，并且记录具有某属性的商品，然后快速生成报表。</p>\n<p>分析：这种场景需要执行大量的任务，我们也会希望任务执行的越快越好。这种情况下，也应该使用多线程策略，并行计算。但与响应速度优先的场景区别在于，这类场景任务量巨大，并不需要瞬时的完成，而是关注如何使用有限的资源，尽可能在单位时间内处理更多的任务，也就是吞吐量优先的问题。所以应该设置队列去缓冲并发任务，调整合适的corePoolSize去设置处理任务的线程数。在这里，设置的线程数过多可能还会引发线程上下文切换频繁的问题，也会降低处理任务的速度，降低吞吐量。</p>\n<p>图片\n图13 并行执行任务提升批量任务执行速度\n3.2 实际问题及方案思考</p>\n<p>线程池使用面临的核心的问题在于：线程池的参数并不好配置。一方面线程池的运行机制不是很好理解，配置合理需要强依赖开发人员的个人经验和知识；另一方面，线程池执行的情况和任务类型相关性较大，IO密集型和CPU密集型的任务运行起来的情况差异非常大，这导致业界并没有一些成熟的经验策略帮助开发人员参考。</p>\n<p>关于线程池配置不合理引发的故障，公司内部有较多记录，下面举一些例子：</p>\n<p>Case1：2018年XX页面展示接口大量调用降级。</p>\n<p>事故描述：XX页面展示接口产生大量调用降级，数量级在几十到上百。</p>\n<p>事故原因：该服务展示接口内部逻辑使用线程池做并行计算，由于没有预估好调用的流量，导致最大核心数设置偏小，大量抛出RejectedExecutionException，触发接口降级条件，示意图如下：</p>\n<p>图片\n图14 线程数核心设置过小引发RejectExecutionException\nCase2：2018年XX业务服务不可用S2级故障。</p>\n<p>事故描述：XX业务提供的服务执行时间过长，作为上游服务整体超时，大量下游服务调用失败。</p>\n<p>事故原因：该服务处理请求内部逻辑使用线程池做资源隔离，由于队列设置过长，最大线程数设置失效，导致请求数量增加时，大量任务堆积在队列中，任务执行时间过长，最终导致下游服务的大量调用超时失败。示意图如下：</p>\n<p>图片\n图15 线程池队列长度设置过长、corePoolSize设置过小导致任务执行速度低\n业务中要使用线程池，而使用不当又会导致故障，那么我们怎样才能更好地使用线程池呢？针对这个问题，我们下面延展几个方向：</p>\n<ol>\n<li>能否不用线程池?</li>\n</ol>\n<p>回到最初的问题，业务使用线程池是为了获取并发性，对于获取并发性，是否可以有什么其他的方案呢替代？我们尝试进行了一些其他方案的调研：</p>\n<p>图片\n综合考虑，这些新的方案都能在某种情况下提升并行任务的性能，然而本次重点解决的问题是如何更简易、更安全地获得的并发性。另外，Actor模型的应用实际上甚少，只在Scala中使用广泛，协程框架在Java中维护的也不成熟。这三者现阶段都不是足够的易用，也并不能解决业务上现阶段的问题。</p>\n<ol start=\"2\">\n<li>追求参数设置合理性？</li>\n</ol>\n<p>有没有一种计算公式，能够让开发同学很简易地计算出某种场景中的线程池应该是什么参数呢？</p>\n<p>带着这样的疑问，我们调研了业界的一些线程池参数配置方案：</p>\n<p>图片\n调研了以上业界方案后，我们并没有得出通用的线程池计算方式。并发任务的执行情况和任务类型相关，IO密集型和CPU密集型的任务运行起来的情况差异非常大，但这种占比是较难合理预估的，这导致很难有一个简单有效的通用公式帮我们直接计算出结果。</p>\n<ol start=\"3\">\n<li>线程池参数动态化？</li>\n</ol>\n<p>尽管经过谨慎的评估，仍然不能够保证一次计算出来合适的参数，那么我们是否可以将修改线程池参数的成本降下来，这样至少可以发生故障的时候可以快速调整从而缩短故障恢复的时间呢？基于这个思考，我们是否可以将线程池的参数从代码中迁移到分布式配置中心上，实现线程池参数可动态配置和即时生效，线程池参数动态化前后的参数修改流程对比如下：</p>\n<p>图片\n图16 动态修改线程池参数新旧流程对比\n基于以上三个方向对比，我们可以看出参数动态化方向简单有效。</p>\n<p>3.3 动态化线程池</p>\n<p>3.3.1 整体设计</p>\n<p>动态化线程池的核心设计包括以下三个方面：</p>\n<p>简化线程池配置：线程池构造参数有8个，但是最核心的是3个：corePoolSize、maximumPoolSize，workQueue，它们最大程度地决定了线程池的任务分配和线程分配策略。考虑到在实际应用中我们获取并发性的场景主要是两种：（1）并行执行子任务，提高响应速度。这种情况下，应该使用同步队列，没有什么任务应该被缓存下来，而是应该立即执行。（2）并行执行大批次任务，提升吞吐量。这种情况下，应该使用有界队列，使用队列去缓冲大批量的任务，队列容量必须声明，防止任务无限制堆积。所以线程池只需要提供这三个关键参数的配置，并且提供两种队列的选择，就可以满足绝大多数的业务需求，Less is More。\n参数可动态修改：为了解决参数不好配，修改参数成本高等问题。在Java线程池留有高扩展性的基础上，封装线程池，允许线程池监听同步外部的消息，根据消息进行修改配置。将线程池的配置放置在平台侧，允许开发同学简单的查看、修改线程池配置。\n增加线程池监控：对某事物缺乏状态的观测，就对其改进无从下手。在线程池执行任务的生命周期添加监控能力，帮助开发同学了解线程池状态。</p>\n<p>图片\n图17 动态化线程池整体设计\n3.3.2 功能架构</p>\n<p>动态化线程池提供如下功能：</p>\n<p>动态调参：支持线程池参数动态调整、界面化操作；包括修改线程池核心大小、最大核心大小、队列长度等；参数修改后及时生效。</p>\n<p>任务监控：支持应用粒度、线程池粒度、任务粒度的Transaction监控；可以看到线程池的任务执行情况、最大任务执行时间、平均任务执行时间、95/99线等。</p>\n<p>负载告警：线程池队列任务积压到一定值的时候会通过大象（美团内部通讯工具）告知应用开发负责人；当线程池负载数达到一定阈值的时候会通过大象告知应用开发负责人。</p>\n<p>操作监控：创建/修改和删除线程池都会通知到应用的开发负责人。</p>\n<p>操作日志：可以查看线程池参数的修改记录，谁在什么时候修改了线程池参数、修改前的参数值是什么。</p>\n<p>权限校验：只有应用开发负责人才能够修改应用的线程池参数。</p>\n<p>图片\n图18 动态化线程池功能架构\n参数动态化</p>\n<p>JDK原生线程池ThreadPoolExecutor提供了如下几个public的setter方法，如下图所示：</p>\n<p>图片\n图19 JDK 线程池参数设置接口\nJDK允许线程池使用方通过ThreadPoolExecutor的实例来动态设置线程池的核心策略，以setCorePoolSize为方法例，在运行期线程池使用方调用此方法设置corePoolSize之后，线程池会直接覆盖原来的corePoolSize值，并且基于当前值和原始值的比较结果采取不同的处理策略。对于当前值小于当前工作线程数的情况，说明有多余的worker线程，此时会向当前idle的worker线程发起中断请求以实现回收，多余的worker在下次idle的时候也会被回收；对于当前值大于原始值且当前队列中有待执行任务，则线程池会创建新的worker线程来执行队列任务，setCorePoolSize具体流程如下：</p>\n<p>图片\n图20 setCorePoolSize方法执行流程\n线程池内部会处理好当前状态做到平滑修改，其他几个方法限于篇幅，这里不一一介绍。重点是基于这几个public方法，我们只需要维护ThreadPoolExecutor的实例，并且在需要修改的时候拿到实例修改其参数即可。基于以上的思路，我们实现了线程池参数的动态化、线程池参数在管理平台可配置可修改，其效果图如下图所示：</p>\n<p>图片\n图21 可动态修改线程池参数\n用户可以在管理平台上通过线程池的名字找到指定的线程池，然后对其参数进行修改，保存后会实时生效。目前支持的动态参数包括核心数、最大值、队列长度等。除此之外，在界面中，我们还能看到用户可以配置是否开启告警、队列等待任务告警阈值、活跃度告警等等。关于监控和告警，我们下面一节会对齐进行介绍。</p>\n<p>线程池监控</p>\n<p>除了参数动态化之外，为了更好地使用线程池，我们需要对线程池的运行状况有感知，比如当前线程池的负载是怎么样的？分配的资源够不够用？任务的执行情况是怎么样的？是长任务还是短任务？</p>\n<p>基于对这些问题的思考，动态化线程池提供了多个维度的监控和告警能力，包括：线程池活跃度、任务的执行Transaction（频率、耗时）、Reject异常、线程池内部统计信息等等，既能帮助用户从多个维度分析线程池的使用情况，又能在出现问题第一时间通知到用户，从而避免故障或加速故障恢复。</p>\n<ol>\n<li>负载监控和告警</li>\n</ol>\n<p>线程池负载关注的核心问题是：基于当前线程池参数分配的资源够不够。对于这个问题，我们可以从事前和事中两个角度来看。事前，线程池定义了“活跃度”这个概念，来让用户在发生Reject异常之前能够感知线程池负载问题，线程池活跃度计算公式为：线程池活跃度 = activeCount/maximumPoolSize。这个公式代表当活跃线程数趋向于maximumPoolSize的时候，代表线程负载趋高。</p>\n<p>事中，也可以从两方面来看线程池的过载判定条件，一个是发生了Reject异常，一个是队列中有等待任务（支持定制阈值）。以上两种情况发生了都会触发告警，告警信息会通过大象推送给服务所关联的负责人。</p>\n<p>图片\n图22 大象告警通知\n2. 任务级精细化监控</p>\n<p>在传统的线程池应用场景中，线程池中的任务执行情况对于用户来说是透明的。比如在一个具体的业务场景中，业务开发申请了一个线程池同时用于执行两种任务，一个是发消息任务、一个是发短信任务，这两类任务实际执行的频率和时长对于用户来说没有一个直观的感受，很可能这两类任务不适合共享一个线程池，但是由于用户无法感知，因此也无从优化。动态化线程池内部实现了任务级别的埋点，且允许为不同的业务任务指定具有业务含义的名称，线程池内部基于这个名称做Transaction打点，基于这个功能，用户可以看到线程池内部任务级别的执行情况，且区分业务，任务监控示意图如下图所示：</p>\n<p>图片\n图23 线程池任务执行监控\n3. 运行时状态实时查看</p>\n<p>用户基于JDK原生线程池ThreadPoolExecutor提供的几个public的getter方法，可以读取到当前线程池的运行状态以及参数，如下图所示：</p>\n<p>图片\n图24 线程池实时运行情况\n动态化线程池基于这几个接口封装了运行时状态实时查看的功能，用户基于这个功能可以了解线程池的实时状态，比如当前有多少个工作线程，执行了多少个任务，队列中等待的任务数等等。效果如下图所示：</p>\n<p>图片\n图25 线程池实时运行情况\n3.4 实践总结</p>\n<p>面对业务中使用线程池遇到的实际问题，我们曾回到支持并发性问题本身来思考有没有取代线程池的方案，也曾尝试着去追求线程池参数设置的合理性，但面对业界方案具体落地的复杂性、可维护性以及真实运行环境的不确定性，我们在前两个方向上可谓“举步维艰”。</p>\n<p>最终，我们回到线程池参数动态化方向上探索，得出一个且可以解决业务问题的方案，虽然本质上还是没有逃离使用线程池的范畴，但是在成本和收益之间，算是取得了一个很好的平衡。成本在于实现动态化以及监控成本不高，收益在于：在不颠覆原有线程池使用方式的基础之上，从降低线程池参数修改的成本以及多维度监控这两个方面降低了故障发生的概率。希望本文提供的动态化线程池思路能对大家有帮助。</p>\n<p>四、参考资料</p>\n<p>[1]JDK 1.8 源码</p>\n<p>[2] 维基百科-线程池</p>\n<p>[3] 更好的使用Java线程池</p>\n<p>[4] 维基百科Pooling(Resource Management)</p>\n<p>[5] 深入理解Java线程池：ThreadPoolExecutor</p>\n<p>[6]《Java并发编程实践》</p>\n<p>五、作者简介\n致远，2018年加入美团点评，美团到店综合研发中心后台开发工程师。\n陆晨，2015年加入美团点评，美团到店综合研发中心后台技术专家。</p>\n<p>----------  END  ----------</p>\n', '2026-02-03 02:13:50', '2026-02-07 02:57:23');

-- ----------------------------
-- Table structure for article_tag_rel
-- ----------------------------
DROP TABLE IF EXISTS `article_tag_rel`;
CREATE TABLE `article_tag_rel`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `article_id` bigint UNSIGNED NOT NULL COMMENT '文章ID',
  `tag_id` bigint UNSIGNED NOT NULL COMMENT '标签ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_article_tag`(`article_id` ASC, `tag_id` ASC) USING BTREE,
  INDEX `idx_tag_id`(`tag_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 302 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文章标签关联表' ROW_FORMAT = DYNAMIC;

